					encoding = Encoding.UTF8;
					num = 1;
					break;
				case '6':
					encoding = Encoding.Unicode;
					num = 2;
					break;
				case '7':
					encoding = Encoding.UTF7;
					num = 1;
					break;
				case 'b':
					encoding = Encoding.BigEndianUnicode;
					num = 2;
					break;
				case '3':
					encoding = Encoding.GetEncoding(12000);
					num = 4;
					break;
				case '4':
