				char c = (char)Read();
				if (c == until)
				{
					break;
				}
				if (handleReferences && c == '&')
				{
					ReadReference();
				}
				else
				{
					buffer.Append(c);
				}
			}
			string result = buffer.ToString();
			buffer.Length = 0;
			return result;
		}

		public string ReadName()
		{
