			{
				throw Error($"Insufficient close tag: {elementNames.Peek()}");
			}
			handler.OnEndParsing(this);
			Cleanup();
		}

		private void Cleanup()
		{
			line = 1;
			column = 0;
			handler = null;
			reader = null;
			elementNames.Clear();
			xmlSpaces.Clear();
			attributes.Clear();
			buffer.Length = 0;
			xmlSpace = null;
			isWhitespace = false;
		}

		public void ReadContent()
