					break;
				}
				default:
				{
					HandleBufferedContent();
					string text = ReadName();
					while (Peek() != 62 && Peek() != 47)
					{
						ReadAttribute(attributes);
					}
					handler.OnStartElement(text, attributes);
					attributes.Clear();
					SkipWhitespaces();
					if (Peek() == 47)
					{
						Read();
						handler.OnEndElement(text);
					}
					else
					{
						elementNames.Push(text);
						xmlSpaces.Push(xmlSpace);
					}
					Expect(62);
					break;
				}
				}
			}
			else
			{
				ReadCharacters();
			}
