		private void HandleBufferedContent()
		{
			if (buffer.Length != 0)
			{
				if (isWhitespace)
				{
					handler.OnIgnorableWhitespace(buffer.ToString());
				}
				else
				{
					handler.OnChars(buffer.ToString());
				}
				buffer.Length = 0;
				isWhitespace = false;
			}
		}

		private void ReadCharacters()
		{
			isWhitespace = false;
			while (true)
			{
				switch (Peek())
				{
				case -1:
				case 60:
					return;
				case 38:
					Read();
					ReadReference();
					break;
				default:
					buffer.Append((char)Read());
					break;
				}
			}
		}

		private void ReadReference()
		{
			if (Peek() == 35)
			{
				Read();
				ReadCharacterReference();
				return;
			}
			string text = ReadName();
			Expect(59);
			switch (text)
			{
			case "amp":
				buffer.Append('&');
				break;
			case "quot":
				buffer.Append('"');
				break;
			case "apos":
				buffer.Append('\'');
				break;
			case "lt":
				buffer.Append('<');
				break;
			case "gt":
				buffer.Append('>');
				break;
			default:
				throw Error("General non-predefined entity reference is not supported in this parser.");
			}
