		private int ReadCharacterReference()
		{
			int num = 0;
			if (Peek() == 120)
			{
				Read();
				for (int num2 = Peek(); num2 >= 0; num2 = Peek())
				{
					if (48 <= num2 && num2 <= 57)
					{
						num <<= 4 + num2 - 48;
					}
					else if (65 <= num2 && num2 <= 70)
					{
						num <<= 4 + num2 - 65 + 10;
					}
					else
					{
						if (97 > num2 || num2 > 102)
						{
							break;
						}
						num <<= 4 + num2 - 97 + 10;
					}
					Read();
				}
			}
			else
			{
				int num3 = Peek();
				while (num3 >= 0 && 48 <= num3 && num3 <= 57)
				{
					num <<= 4 + num3 - 48;
					Read();
					num3 = Peek();
				}
			}
			return num;
		}

		private void ReadAttribute(AttrListImpl a)
		{
			SkipWhitespaces(expected: true);
			if (Peek() != 47 && Peek() != 62)
			{
				string text = ReadName();
				SkipWhitespaces();
				Expect(61);
				SkipWhitespaces();
				string value = Read() switch
				{
					39 => ReadUntil('\'', handleReferences: true), 
					34 => ReadUntil('"', handleReferences: true), 
					_ => throw Error("Invalid attribute value markup."), 
				};
				if (text == "xml:space")
				{
					xmlSpace = value;
				}
				a.Add(text, value);
			}
		}

		private void ReadCDATASection()
		{
			int num = 0;
			while (Peek() >= 0)
			{
				char c = (char)Read();
				switch (c)
				{
				case ']':
					num++;
					continue;
				case '>':
					if (num > 1)
					{
						for (int num2 = num; num2 > 2; num2--)
						{
							buffer.Append(']');
						}
						return;
					}
					break;
				}
				for (int i = 0; i < num; i++)
				{
					buffer.Append(']');
				}
				num = 0;
				buffer.Append(c);
			}
			throw UnexpectedEndError();
		}

		private void ReadComment()
		{
			Expect(45);
			Expect(45);
			while (Read() != 45 || Read() != 45)
			{
			}
			if (Read() != 62)
			{
				throw Error("'--' is not allowed inside comment markup.");
			}
		}
	}
