		private void GenerateKeyPair()
		{
			int num = KeySize + 1 >> 1;
			int bits = KeySize - num;
			e = 65537u;
			do
			{
				p = BigInteger.GeneratePseudoPrime(num);
			}
			while (p % 65537u == 1);
			while (true)
			{
				q = BigInteger.GeneratePseudoPrime(bits);
				if (q % 65537u != 1 && p != q)
				{
					n = p * q;
					if (n.BitCount() == KeySize)
