						break;
					}
					if (p < q)
					{
						p = q;
					}
				}
			}
			BigInteger bigInteger = p - 1;
			BigInteger bigInteger2 = q - 1;
			BigInteger modulus = bigInteger * bigInteger2;
			d = e.ModInverse(modulus);
			dp = d % bigInteger;
			dq = d % bigInteger2;
