				for (int i = 0; i < num2; i++)
				{
					enc.TransformBlock(rgb, num, blockSize, block, 0);
					num += blockSize;
				}
				blockCount = cb - num;
				if (blockCount > 0)
				{
					Array.Copy(rgb, num, block, 0, blockCount);
