		public void SetBit(uint bitNum, bool value)
		{
			uint num = bitNum >> 5;
			if (num < length)
			{
				uint num2 = (uint)(1 << (int)(bitNum & 0x1F));
				if (value)
				{
					data[num] |= num2;
				}
				else
				{
					data[num] &= ~num2;
				}
			}
		}

		public int LowestSetBit()
		{
			if (this == 0u)
			{
				return -1;
