							break;
						case TokenType.SEP_HourSuff:
						case TokenType.SEP_MinuteSuff:
						case TokenType.SEP_SecondSuff:
							dtok.dtt = DTT.NumTimesuff;
							dtok.suffix = separatorToken;
							break;
