		private static bool VerifyValidPunctuation(ref __DTString str)
		{
			switch (str.Value[str.Index])
			{
			case '#':
			{
				bool flag = false;
				bool flag2 = false;
				for (int j = 0; j < str.Length; j++)
				{
					char c = str.Value[j];
					switch (c)
					{
					case '#':
						if (flag)
						{
							if (flag2)
							{
								return false;
							}
							flag2 = true;
						}
						else
						{
							flag = true;
						}
						break;
					case '\0':
						if (!flag2)
						{
							return false;
						}
						break;
					default:
						if (!char.IsWhiteSpace(c) && (!flag || flag2))
						{
							return false;
						}
						break;
					}
				}
				if (!flag2)
				{
					return false;
				}
				str.GetNext();
				return true;
			}
			case '\0':
			{
				for (int i = str.Index; i < str.Length; i++)
				{
					if (str.Value[i] != 0)
					{
						return false;
					}
				}
				str.Index = str.Length;
				return true;
			}
			default:
				return false;
			}
		}

