					flag = !flag;
					break;
				}
				if (flag)
				{
					continue;
				}
				switch (c)
				{
				case 'y':
					num = num4++;
					for (; i + 1 < datePattern.Length && datePattern[i + 1] == 'y'; i++)
					{
					}
					break;
				case 'M':
					num2 = num4++;
					for (; i + 1 < datePattern.Length && datePattern[i + 1] == 'M'; i++)
					{
					}
