			if (float.IsNaN(y))
			{
				return y;
			}
			float num = x % y;
			if (float.IsNaN(num))
			{
				return float.NaN;
			}
			if (num == 0f && float.IsNegative(x))
			{
				return -0f;
			}
			float num2 = num - Abs(y) * (float)Sign(x);
			if (Abs(num2) == Abs(num))
			{
				float x2 = x / y;
				if (Abs(Round(x2)) > Abs(x2))
				{
