		private struct SorterObjectArray
		{
			private object[] keys;

			private object[] items;

			private IComparer comparer;

			internal SorterObjectArray(object[] keys, object[] items, IComparer comparer)
			{
				if (comparer == null)
				{
					comparer = Comparer.Default;
				}
				this.keys = keys;
				this.items = items;
				this.comparer = comparer;
			}

			internal void SwapIfGreaterWithItems(int a, int b)
			{
				if (a != b && comparer.Compare(keys[a], keys[b]) > 0)
				{
					object obj = keys[a];
					keys[a] = keys[b];
					keys[b] = obj;
					if (items != null)
					{
						object obj2 = items[a];
						items[a] = items[b];
						items[b] = obj2;
					}
				}
			}

			private void Swap(int i, int j)
			{
				object obj = keys[i];
				keys[i] = keys[j];
				keys[j] = obj;
				if (items != null)
				{
					object obj2 = items[i];
					items[i] = items[j];
					items[j] = obj2;
				}
			}

			internal void Sort(int left, int length)
			{
				IntrospectiveSort(left, length);
			}

			private void IntrospectiveSort(int left, int length)
			{
				if (length < 2)
				{
					return;
				}
				try
				{
					IntroSort(left, length + left - 1, 2 * IntrospectiveSortUtilities.FloorLog2PlusOne(keys.Length));
				}
				catch (IndexOutOfRangeException)
				{
					IntrospectiveSortUtilities.ThrowOrIgnoreBadComparer(comparer);
				}
				catch (Exception innerException)
				{
					throw new InvalidOperationException("Failed to compare two elements in the array.", innerException);
				}
			}

			private void IntroSort(int lo, int hi, int depthLimit)
			{
				while (hi > lo)
				{
					int num = hi - lo + 1;
					if (num <= 16)
					{
						switch (num)
						{
						case 1:
							break;
						case 2:
							SwapIfGreaterWithItems(lo, hi);
							break;
						case 3:
							SwapIfGreaterWithItems(lo, hi - 1);
							SwapIfGreaterWithItems(lo, hi);
							SwapIfGreaterWithItems(hi - 1, hi);
							break;
						default:
							InsertionSort(lo, hi);
							break;
						}
						break;
					}
					if (depthLimit == 0)
					{
						Heapsort(lo, hi);
						break;
					}
					depthLimit--;
					int num2 = PickPivotAndPartition(lo, hi);
					IntroSort(num2 + 1, hi, depthLimit);
					hi = num2 - 1;
				}
			}

			private int PickPivotAndPartition(int lo, int hi)
			{
				int num = lo + (hi - lo) / 2;
				SwapIfGreaterWithItems(lo, num);
				SwapIfGreaterWithItems(lo, hi);
				SwapIfGreaterWithItems(num, hi);
				object obj = keys[num];
				Swap(num, hi - 1);
				int num2 = lo;
				int num3 = hi - 1;
				while (num2 < num3)
				{
					while (comparer.Compare(keys[++num2], obj) < 0)
					{
					}
					while (comparer.Compare(obj, keys[--num3]) < 0)
					{
					}
					if (num2 >= num3)
					{
						break;
					}
					Swap(num2, num3);
				}
				Swap(num2, hi - 1);
				return num2;
			}

			private void Heapsort(int lo, int hi)
			{
				int num = hi - lo + 1;
				for (int num2 = num / 2; num2 >= 1; num2--)
				{
					DownHeap(num2, num, lo);
				}
				for (int num3 = num; num3 > 1; num3--)
				{
					Swap(lo, lo + num3 - 1);
					DownHeap(1, num3 - 1, lo);
				}
			}

			private void DownHeap(int i, int n, int lo)
			{
				object obj = keys[lo + i - 1];
				object obj2 = ((items != null) ? items[lo + i - 1] : null);
				while (i <= n / 2)
				{
					int num = 2 * i;
					if (num < n && comparer.Compare(keys[lo + num - 1], keys[lo + num]) < 0)
					{
						num++;
					}
					if (comparer.Compare(obj, keys[lo + num - 1]) >= 0)
					{
						break;
					}
					keys[lo + i - 1] = keys[lo + num - 1];
					if (items != null)
					{
						items[lo + i - 1] = items[lo + num - 1];
					}
					i = num;
				}
				keys[lo + i - 1] = obj;
				if (items != null)
				{
					items[lo + i - 1] = obj2;
				}
			}

			private void InsertionSort(int lo, int hi)
			{
				for (int i = lo; i < hi; i++)
				{
					int num = i;
					object obj = keys[i + 1];
					object obj2 = ((items != null) ? items[i + 1] : null);
					while (num >= lo && comparer.Compare(obj, keys[num]) < 0)
					{
						keys[num + 1] = keys[num];
						if (items != null)
						{
							items[num + 1] = items[num];
						}
						num--;
					}
					keys[num + 1] = obj;
					if (items != null)
					{
						items[num + 1] = obj2;
					}
				}
			}
		}

