						keys.SetValue(keys.GetValue(num), num + 1);
						if (items != null)
						{
							items.SetValue(items.GetValue(num), num + 1);
						}
						num--;
					}
					keys.SetValue(value, num + 1);
					if (items != null)
					{
						items.SetValue(value2, num + 1);
					}
				}
