	[StructLayout(LayoutKind.Auto)]
	public struct ArgIterator
	{
		private IntPtr sig;

		private IntPtr args;

		private int next_arg;

		private int num_args;

		[MethodImpl(MethodImplOptions.InternalCall)]
		private extern void Setup(IntPtr argsp, IntPtr start);

		public ArgIterator(RuntimeArgumentHandle arglist)
		{
			sig = IntPtr.Zero;
			args = IntPtr.Zero;
			next_arg = (num_args = 0);
			if (arglist.args == IntPtr.Zero)
			{
				throw new PlatformNotSupportedException();
			}
			Setup(arglist.args, IntPtr.Zero);
		}

		[CLSCompliant(false)]
		public unsafe ArgIterator(RuntimeArgumentHandle arglist, void* ptr)
		{
			sig = IntPtr.Zero;
			args = IntPtr.Zero;
			next_arg = (num_args = 0);
			if (arglist.args == IntPtr.Zero)
			{
				throw new PlatformNotSupportedException();
			}
			Setup(arglist.args, (IntPtr)ptr);
		}

		public void End()
		{
			next_arg = num_args;
		}

		public override bool Equals(object o)
		{
			throw new NotSupportedException("ArgIterator does not support Equals.");
		}

		public override int GetHashCode()
		{
			return sig.GetHashCode();
		}

		[CLSCompliant(false)]
		public unsafe TypedReference GetNextArg()
		{
			if (num_args == next_arg)
			{
				throw new InvalidOperationException("Invalid iterator position.");
			}
			TypedReference result = default(TypedReference);
			IntGetNextArg(&result);
			return result;
		}

		[MethodImpl(MethodImplOptions.InternalCall)]
		private unsafe extern void IntGetNextArg(void* res);

		[CLSCompliant(false)]
		public unsafe TypedReference GetNextArg(RuntimeTypeHandle rth)
		{
			if (num_args == next_arg)
			{
				throw new InvalidOperationException("Invalid iterator position.");
			}
			TypedReference result = default(TypedReference);
			IntGetNextArgWithType(&result, rth.Value);
			return result;
		}

		[MethodImpl(MethodImplOptions.InternalCall)]
		private unsafe extern void IntGetNextArgWithType(void* res, IntPtr rth);

		public RuntimeTypeHandle GetNextArgType()
		{
			if (num_args == next_arg)
			{
				throw new InvalidOperationException("Invalid iterator position.");
			}
			return new RuntimeTypeHandle(IntGetNextArgType());
		}

		[MethodImpl(MethodImplOptions.InternalCall)]
		private extern IntPtr IntGetNextArgType();

		public int GetRemainingCount()
		{
			return num_args - next_arg;
		}
	}
	public static class Console
	{
		private class WindowsConsole
		{
			private delegate bool WindowsCancelHandler(int keyCode);

			public static bool ctrlHandlerAdded = false;

			private static WindowsCancelHandler cancelHandler = DoWindowsConsoleCancelEvent;

			[DllImport("kernel32.dll", CharSet = CharSet.Auto, ExactSpelling = true)]
			private static extern int GetConsoleCP();

			[DllImport("kernel32.dll", CharSet = CharSet.Auto, ExactSpelling = true)]
			private static extern int GetConsoleOutputCP();

			[DllImport("kernel32.dll", CharSet = CharSet.Auto, ExactSpelling = true)]
			private static extern bool SetConsoleCtrlHandler(WindowsCancelHandler handler, bool addHandler);

			private static bool DoWindowsConsoleCancelEvent(int keyCode)
			{
				if (keyCode == 0)
				{
					DoConsoleCancelEvent();
				}
				return keyCode == 0;
			}

			[MethodImpl(MethodImplOptions.NoInlining)]
			public static int GetInputCodePage()
			{
				return GetConsoleCP();
			}

			[MethodImpl(MethodImplOptions.NoInlining)]
			public static int GetOutputCodePage()
			{
				return GetConsoleOutputCP();
			}

			public static void AddCtrlHandler()
			{
				SetConsoleCtrlHandler(cancelHandler, addHandler: true);
				ctrlHandlerAdded = true;
			}

			public static void RemoveCtrlHandler()
			{
				SetConsoleCtrlHandler(cancelHandler, addHandler: false);
				ctrlHandlerAdded = false;
			}
		}

