			ulong num4 = lo - num3 * 100000000 + num2 * 9551616;
			hi = num;
			lo = num3 + num2 * 184467440737L;
			num3 = num4 / 100000000;
			num4 -= num3 * 100000000;
			lo += num3;
			_val1 = ToDecHex((int)num4);
			num3 = lo / 100000000;
			num4 = lo - num3 * 100000000;
			lo = num3;
			if (hi != 0)
			{
				lo += (ulong)((long)hi * 184467440737L);
				num4 += (ulong)((long)hi * 9551616L);
				num3 = num4 / 100000000;
				lo += num3;
				num4 -= num3 * 100000000;
