			ulong num2 = _val1 | ((ulong)_val2 << 32);
			while (num > 0)
			{
				_cbuf[--num] = ptr[num2 & 0xF];
				num2 >>= 4;
			}
			return new string(_cbuf, 0, _ind);
		}

		private string FormatFixedPoint(int precision, NumberFormatInfo nfi)
		{
			if (precision == -1)
			{
