			{
				return t.GUID;
			}
			Type baseType = t.BaseType;
			while (baseType != typeof(object))
			{
				if (baseType.IsImport)
				{
					return baseType.GUID;
				}
				baseType = baseType.BaseType;
			}
			throw new COMException("Could not find base COM type for type " + t.ToString());
		}

