			private readonly object _value3;

			public ThreeElementAsyncLocalValueMap(IAsyncLocal key1, object value1, IAsyncLocal key2, object value2, IAsyncLocal key3, object value3)
			{
				_key1 = key1;
				_value1 = value1;
				_key2 = key2;
				_value2 = value2;
				_key3 = key3;
				_value3 = value3;
