					{
					}
					finally
					{
						bool missedSteal = false;
						workQueue.Dequeue(tl, out callback, out missedSteal);
						if (callback == null)
						{
							flag = missedSteal;
						}
						else
						{
							workQueue.EnsureThreadRequested();
