								flag2 = true;
							}
							callback.ExecuteWorkItem();
							callback = null;
						}
						finally
						{
							if (flag2)
							{
								ThreadPool.ReportThreadStatus(isWorking: false);
							}
						}
					}
					else
					{
						callback.ExecuteWorkItem();
						callback = null;
					}
					if (!ThreadPool.NotifyWorkItemComplete())
