	[Serializable]
	[ComVisible(true)]
	public sealed class UnionCodeGroup : CodeGroup
	{
		public override string MergeLogic => "Union";

		public UnionCodeGroup(IMembershipCondition membershipCondition, PolicyStatement policy)
			: base(membershipCondition, policy)
		{
		}

		internal UnionCodeGroup(SecurityElement e, PolicyLevel level)
			: base(e, level)
		{
		}

		public override CodeGroup Copy()
		{
			return Copy(childs: true);
		}

		internal CodeGroup Copy(bool childs)
		{
			UnionCodeGroup unionCodeGroup = new UnionCodeGroup(base.MembershipCondition, base.PolicyStatement);
			unionCodeGroup.Name = base.Name;
			unionCodeGroup.Description = base.Description;
			if (childs)
			{
				foreach (CodeGroup child in base.Children)
				{
					unionCodeGroup.AddChild(child.Copy());
				}
			}
			return unionCodeGroup;
		}

		public override PolicyStatement Resolve(Evidence evidence)
		{
			if (evidence == null)
			{
				throw new ArgumentNullException("evidence");
			}
			if (!base.MembershipCondition.Check(evidence))
			{
				return null;
			}
			PermissionSet permissionSet = base.PolicyStatement.PermissionSet.Copy();
			if (base.Children.Count > 0)
			{
				foreach (CodeGroup child in base.Children)
				{
					PolicyStatement policyStatement = child.Resolve(evidence);
					if (policyStatement != null)
					{
						permissionSet = permissionSet.Union(policyStatement.PermissionSet);
					}
				}
			}
			PolicyStatement policyStatement2 = base.PolicyStatement.Copy();
			policyStatement2.PermissionSet = permissionSet;
			return policyStatement2;
		}

		public override CodeGroup ResolveMatchingCodeGroups(Evidence evidence)
		{
			if (evidence == null)
			{
				throw new ArgumentNullException("evidence");
			}
			if (!base.MembershipCondition.Check(evidence))
			{
				return null;
			}
			CodeGroup codeGroup = Copy(childs: false);
			if (base.Children.Count > 0)
			{
				foreach (CodeGroup child in base.Children)
				{
					CodeGroup codeGroup2 = child.ResolveMatchingCodeGroups(evidence);
					if (codeGroup2 != null)
					{
						codeGroup.AddChild(codeGroup2);
					}
				}
			}
			return codeGroup;
		}
	}
	[Serializable]
	[ComVisible(true)]
	public sealed class Url : EvidenceBase, IIdentityPermissionFactory, IBuiltInEvidence
	{
		private string origin_url;

		public string Value => origin_url;

		public Url(string name)
			: this(name, validated: false)
		{
		}

		internal Url(string name, bool validated)
		{
			origin_url = (validated ? name : Prepare(name));
		}

		public object Copy()
		{
			return new Url(origin_url, validated: true);
		}

		public IPermission CreateIdentityPermission(Evidence evidence)
		{
			return new UrlIdentityPermission(origin_url);
		}

		public override bool Equals(object o)
		{
			if (!(o is Url { Value: var text }))
			{
				return false;
			}
			string text2 = origin_url;
			if (text.IndexOf(Uri.SchemeDelimiter) < 0)
			{
				text = "file://" + text;
			}
			if (text2.IndexOf(Uri.SchemeDelimiter) < 0)
			{
				text2 = "file://" + text2;
			}
			return string.Compare(text, text2, ignoreCase: true, CultureInfo.InvariantCulture) == 0;
		}

		public override int GetHashCode()
		{
			string text = origin_url;
			if (text.IndexOf(Uri.SchemeDelimiter) < 0)
			{
				text = "file://" + text;
			}
			return text.GetHashCode();
		}

		public override string ToString()
		{
			SecurityElement securityElement = new SecurityElement("System.Security.Policy.Url");
			securityElement.AddAttribute("version", "1");
			securityElement.AddChild(new SecurityElement("Url", origin_url));
			return securityElement.ToString();
		}

		int IBuiltInEvidence.GetRequiredSize(bool verbose)
		{
			return ((!verbose) ? 1 : 3) + origin_url.Length;
		}

		[MonoTODO("IBuiltInEvidence")]
		int IBuiltInEvidence.InitFromBuffer(char[] buffer, int position)
		{
			return 0;
		}

		[MonoTODO("IBuiltInEvidence")]
		int IBuiltInEvidence.OutputToBuffer(char[] buffer, int position, bool verbose)
		{
			return 0;
		}

		private string Prepare(string url)
		{
			if (url == null)
			{
				throw new ArgumentNullException("Url");
			}
			if (url == string.Empty)
			{
				throw new FormatException(Locale.GetText("Invalid (empty) Url"));
			}
			if (url.IndexOf(Uri.SchemeDelimiter) > 0)
			{
				if (url.StartsWith("file://"))
				{
					url = "file://" + url.Substring(7);
				}
				url = new Uri(url, dontEscape: false, reduce: false).ToString();
			}
			int num = url.Length - 1;
			if (url[num] == '/')
			{
				url = url.Substring(0, num);
			}
			return url;
		}
	}
	[Serializable]
	[ComVisible(true)]
	public sealed class UrlMembershipCondition : IMembershipCondition, ISecurityEncodable, ISecurityPolicyEncodable, IConstantMembershipCondition
	{
		private readonly int version = 1;

		private Url url;

		private string userUrl;

		public string Url
		{
			get
			{
				if (userUrl == null)
				{
					userUrl = url.Value;
				}
				return userUrl;
			}
			set
			{
				url = new Url(value);
			}
		}

		public UrlMembershipCondition(string url)
		{
			if (url == null)
			{
				throw new ArgumentNullException("url");
			}
			CheckUrl(url);
			userUrl = url;
			this.url = new Url(url);
		}

		internal UrlMembershipCondition(Url url, string userUrl)
		{
			this.url = (Url)url.Copy();
			this.userUrl = userUrl;
		}

		public bool Check(Evidence evidence)
		{
			if (evidence == null)
			{
				return false;
			}
			string value = url.Value;
			int num = value.LastIndexOf("*");
			if (num == -1)
			{
				num = value.Length;
			}
			System.Collections.IEnumerator hostEnumerator = evidence.GetHostEnumerator();
			while (hostEnumerator.MoveNext())
			{
				if (hostEnumerator.Current is Url && string.Compare(value, 0, (hostEnumerator.Current as Url).Value, 0, num, ignoreCase: true, CultureInfo.InvariantCulture) == 0)
				{
					return true;
				}
			}
			return false;
		}

		public IMembershipCondition Copy()
		{
			return new UrlMembershipCondition(url, userUrl);
		}

		public override bool Equals(object o)
		{
			UrlMembershipCondition urlMembershipCondition = o as UrlMembershipCondition;
			if (o == null)
			{
				return false;
			}
			string value = url.Value;
			int num = value.Length;
			if (value[num - 1] == '*')
			{
				num--;
				if (value[num - 1] == '/')
				{
					num--;
				}
			}
			return string.Compare(value, 0, urlMembershipCondition.Url, 0, num, ignoreCase: true, CultureInfo.InvariantCulture) == 0;
		}

		public void FromXml(SecurityElement e)
		{
			FromXml(e, null);
		}

		public void FromXml(SecurityElement e, PolicyLevel level)
		{
			MembershipConditionHelper.CheckSecurityElement(e, "e", version, version);
			string text = e.Attribute("Url");
			if (text != null)
			{
				CheckUrl(text);
				url = new Url(text);
			}
			else
			{
				url = null;
			}
			userUrl = text;
		}

		public override int GetHashCode()
		{
			return url.GetHashCode();
		}

		public override string ToString()
		{
			return "Url - " + Url;
		}

		public SecurityElement ToXml()
		{
			return ToXml(null);
		}

		public SecurityElement ToXml(PolicyLevel level)
		{
			SecurityElement securityElement = MembershipConditionHelper.Element(typeof(UrlMembershipCondition), version);
			securityElement.AddAttribute("Url", userUrl);
			return securityElement;
		}

		internal void CheckUrl(string url)
		{
			if (new Uri((url.IndexOf(Uri.SchemeDelimiter) < 0) ? ("file://" + url) : url, dontEscape: false, reduce: false).Host.IndexOf('*') >= 1)
			{
				throw new ArgumentException(Locale.GetText("Invalid * character in url"), "name");
			}
		}
	}
	[Serializable]
	[ComVisible(true)]
	public sealed class Zone : EvidenceBase, IIdentityPermissionFactory, IBuiltInEvidence
	{
		private SecurityZone zone;

		public SecurityZone SecurityZone => zone;

		public Zone(SecurityZone zone)
		{
			if (!Enum.IsDefined(typeof(SecurityZone), zone))
			{
				throw new ArgumentException(string.Format(Locale.GetText("Invalid zone {0}."), zone), "zone");
			}
			this.zone = zone;
		}

		public object Copy()
		{
			return new Zone(zone);
		}

		public IPermission CreateIdentityPermission(Evidence evidence)
		{
			return new ZoneIdentityPermission(zone);
		}

		[MonoTODO("Not user configurable yet")]
		public static Zone CreateFromUrl(string url)
		{
			if (url == null)
			{
				throw new ArgumentNullException("url");
			}
			SecurityZone securityZone = SecurityZone.NoZone;
			if (url.Length == 0)
			{
				return new Zone(securityZone);
			}
			Uri uri = null;
			try
			{
				uri = new Uri(url);
			}
			catch
			{
				return new Zone(securityZone);
			}
			if (securityZone == SecurityZone.NoZone)
			{
				securityZone = (uri.IsFile ? ((!File.Exists(uri.LocalPath)) ? ((string.Compare("FILE://", 0, url, 0, 7, ignoreCase: true, CultureInfo.InvariantCulture) == 0) ? SecurityZone.Intranet : SecurityZone.Internet) : SecurityZone.MyComputer) : (uri.IsLoopback ? SecurityZone.Intranet : SecurityZone.Internet));
			}
			return new Zone(securityZone);
		}

		public override bool Equals(object o)
		{
			if (!(o is Zone zone))
			{
				return false;
			}
			return zone.zone == this.zone;
		}

		public override int GetHashCode()
		{
			return (int)zone;
		}

		public override string ToString()
		{
			SecurityElement securityElement = new SecurityElement("System.Security.Policy.Zone");
			securityElement.AddAttribute("version", "1");
			securityElement.AddChild(new SecurityElement("Zone", zone.ToString()));
			return securityElement.ToString();
		}

		int IBuiltInEvidence.GetRequiredSize(bool verbose)
		{
			return 3;
		}

		int IBuiltInEvidence.InitFromBuffer(char[] buffer, int position)
		{
			_ = buffer[position++];
			_ = buffer[position++];
			return position;
		}

		int IBuiltInEvidence.OutputToBuffer(char[] buffer, int position, bool verbose)
		{
			buffer[position++] = '\u0003';
			buffer[position++] = (char)((int)zone >> 16);
			buffer[position++] = (char)(zone & (SecurityZone)65535);
			return position;
		}
	}
	[Serializable]
	[ComVisible(true)]
	public sealed class ZoneMembershipCondition : IMembershipCondition, ISecurityEncodable, ISecurityPolicyEncodable, IConstantMembershipCondition
	{
		private readonly int version = 1;

		private SecurityZone zone;

		public SecurityZone SecurityZone
		{
			get
			{
				return zone;
			}
			set
			{
				if (!Enum.IsDefined(typeof(SecurityZone), value))
				{
					throw new ArgumentException(Locale.GetText("invalid zone"));
				}
				if (value == SecurityZone.NoZone)
				{
					throw new ArgumentException(Locale.GetText("NoZone isn't valid for membership condition"));
				}
				zone = value;
			}
		}

		internal ZoneMembershipCondition()
		{
		}

		public ZoneMembershipCondition(SecurityZone zone)
		{
			SecurityZone = zone;
		}

		public bool Check(Evidence evidence)
		{
			if (evidence == null)
			{
				return false;
			}
			System.Collections.IEnumerator hostEnumerator = evidence.GetHostEnumerator();
			while (hostEnumerator.MoveNext())
			{
				if (hostEnumerator.Current is Zone zone && zone.SecurityZone == this.zone)
				{
					return true;
				}
			}
			return false;
		}

		public IMembershipCondition Copy()
		{
			return new ZoneMembershipCondition(zone);
		}

		public override bool Equals(object o)
		{
			if (!(o is ZoneMembershipCondition zoneMembershipCondition))
			{
				return false;
			}
			return zoneMembershipCondition.SecurityZone == zone;
		}

		public void FromXml(SecurityElement e)
		{
