	[ComVisible(true)]
	public abstract class SymmetricAlgorithm : IDisposable
	{
		protected int BlockSizeValue;

		protected int FeedbackSizeValue;

		protected byte[] IVValue;

		protected byte[] KeyValue;

		protected KeySizes[] LegalBlockSizesValue;

		protected KeySizes[] LegalKeySizesValue;

		protected int KeySizeValue;

		protected CipherMode ModeValue;

		protected PaddingMode PaddingValue;

		public virtual int BlockSize
		{
			get
			{
				return BlockSizeValue;
			}
			set
			{
				for (int i = 0; i < LegalBlockSizesValue.Length; i++)
				{
					if (LegalBlockSizesValue[i].SkipSize == 0)
					{
						if (LegalBlockSizesValue[i].MinSize == value)
						{
							BlockSizeValue = value;
							IVValue = null;
							return;
						}
						continue;
					}
					for (int j = LegalBlockSizesValue[i].MinSize; j <= LegalBlockSizesValue[i].MaxSize; j += LegalBlockSizesValue[i].SkipSize)
					{
						if (j == value)
						{
							if (BlockSizeValue != value)
							{
								BlockSizeValue = value;
								IVValue = null;
							}
							return;
						}
					}
				}
				throw new CryptographicException(Environment.GetResourceString("Specified block size is not valid for this algorithm."));
			}
		}

		public virtual int FeedbackSize
		{
			get
			{
				return FeedbackSizeValue;
			}
			set
			{
				if (value <= 0 || value > BlockSizeValue || value % 8 != 0)
				{
					throw new CryptographicException(Environment.GetResourceString("Specified feedback size is invalid."));
				}
				FeedbackSizeValue = value;
			}
		}

		public virtual byte[] IV
		{
			get
			{
				if (IVValue == null)
				{
					GenerateIV();
				}
				return (byte[])IVValue.Clone();
			}
			set
			{
				if (value == null)
				{
					throw new ArgumentNullException("value");
				}
				if (value.Length != BlockSizeValue / 8)
				{
					throw new CryptographicException(Environment.GetResourceString("Specified initialization vector (IV) does not match the block size for this algorithm."));
				}
				IVValue = (byte[])value.Clone();
			}
		}

		public virtual byte[] Key
		{
			get
			{
				if (KeyValue == null)
				{
					GenerateKey();
				}
				return (byte[])KeyValue.Clone();
			}
			set
			{
				if (value == null)
				{
					throw new ArgumentNullException("value");
				}
				if (!ValidKeySize(value.Length * 8))
				{
					throw new CryptographicException(Environment.GetResourceString("Specified key is not a valid size for this algorithm."));
				}
				KeyValue = (byte[])value.Clone();
				KeySizeValue = value.Length * 8;
			}
		}

		public virtual KeySizes[] LegalBlockSizes => (KeySizes[])LegalBlockSizesValue.Clone();

		public virtual KeySizes[] LegalKeySizes => (KeySizes[])LegalKeySizesValue.Clone();

		public virtual int KeySize
		{
			get
			{
				return KeySizeValue;
			}
			set
			{
				if (!ValidKeySize(value))
				{
					throw new CryptographicException(Environment.GetResourceString("Specified key is not a valid size for this algorithm."));
				}
				KeySizeValue = value;
				KeyValue = null;
			}
		}

		public virtual CipherMode Mode
		{
			get
			{
				return ModeValue;
			}
			set
			{
				if (value < CipherMode.CBC || CipherMode.CFB < value)
				{
					throw new CryptographicException(Environment.GetResourceString("Specified cipher mode is not valid for this algorithm."));
				}
				ModeValue = value;
			}
		}

		public virtual PaddingMode Padding
		{
			get
			{
				return PaddingValue;
			}
			set
			{
				if (value < PaddingMode.None || PaddingMode.ISO10126 < value)
				{
					throw new CryptographicException(Environment.GetResourceString("Specified padding mode is not valid for this algorithm."));
				}
				PaddingValue = value;
			}
		}

		protected SymmetricAlgorithm()
		{
			ModeValue = CipherMode.CBC;
			PaddingValue = PaddingMode.PKCS7;
		}

		public void Dispose()
		{
			Dispose(disposing: true);
			GC.SuppressFinalize(this);
		}

		public void Clear()
		{
			((IDisposable)this).Dispose();
		}

		protected virtual void Dispose(bool disposing)
		{
			if (disposing)
			{
				if (KeyValue != null)
				{
					Array.Clear(KeyValue, 0, KeyValue.Length);
					KeyValue = null;
				}
				if (IVValue != null)
				{
					Array.Clear(IVValue, 0, IVValue.Length);
					IVValue = null;
				}
			}
		}

		public bool ValidKeySize(int bitLength)
		{
			KeySizes[] legalKeySizes = LegalKeySizes;
			if (legalKeySizes == null)
			{
				return false;
			}
			for (int i = 0; i < legalKeySizes.Length; i++)
			{
				if (legalKeySizes[i].SkipSize == 0)
				{
					if (legalKeySizes[i].MinSize == bitLength)
					{
						return true;
					}
					continue;
				}
				for (int j = legalKeySizes[i].MinSize; j <= legalKeySizes[i].MaxSize; j += legalKeySizes[i].SkipSize)
				{
					if (j == bitLength)
					{
						return true;
					}
				}
			}
			return false;
		}

		public static SymmetricAlgorithm Create()
		{
			return Create("System.Security.Cryptography.SymmetricAlgorithm");
		}

		public static SymmetricAlgorithm Create(string algName)
		{
			return (SymmetricAlgorithm)CryptoConfig.CreateFromName(algName);
		}

		public virtual ICryptoTransform CreateEncryptor()
		{
			return CreateEncryptor(Key, IV);
		}

		public abstract ICryptoTransform CreateEncryptor(byte[] rgbKey, byte[] rgbIV);

		public virtual ICryptoTransform CreateDecryptor()
		{
			return CreateDecryptor(Key, IV);
		}

		public abstract ICryptoTransform CreateDecryptor(byte[] rgbKey, byte[] rgbIV);

		public abstract void GenerateKey();

		public abstract void GenerateIV();
	}
	[ComVisible(true)]
	public abstract class TripleDES : SymmetricAlgorithm
	{
		private static KeySizes[] s_legalBlockSizes = new KeySizes[1]
		{
			new KeySizes(64, 64, 0)
		};

		private static KeySizes[] s_legalKeySizes = new KeySizes[1]
		{
			new KeySizes(128, 192, 64)
		};

		public override byte[] Key
		{
			get
			{
				if (KeyValue == null)
				{
					do
					{
						GenerateKey();
					}
					while (IsWeakKey(KeyValue));
				}
				return (byte[])KeyValue.Clone();
			}
			set
			{
				if (value == null)
				{
					throw new ArgumentNullException("value");
				}
				if (!ValidKeySize(value.Length * 8))
				{
					throw new CryptographicException(Environment.GetResourceString("Specified key is not a valid size for this algorithm."));
				}
				if (IsWeakKey(value))
				{
					throw new CryptographicException(Environment.GetResourceString("Specified key is a known weak key for '{0}' and cannot be used."), "TripleDES");
				}
				KeyValue = (byte[])value.Clone();
				KeySizeValue = value.Length * 8;
			}
		}

		protected TripleDES()
		{
			KeySizeValue = 192;
			BlockSizeValue = 64;
			FeedbackSizeValue = BlockSizeValue;
			LegalBlockSizesValue = s_legalBlockSizes;
			LegalKeySizesValue = s_legalKeySizes;
		}

		public new static TripleDES Create()
		{
			return Create("System.Security.Cryptography.TripleDES");
		}

		public new static TripleDES Create(string str)
		{
			return (TripleDES)CryptoConfig.CreateFromName(str);
		}

		public static bool IsWeakKey(byte[] rgbKey)
		{
			if (!IsLegalKeySize(rgbKey))
			{
				throw new CryptographicException(Environment.GetResourceString("Specified key is not a valid size for this algorithm."));
			}
			byte[] array = Utils.FixupKeyParity(rgbKey);
			if (EqualBytes(array, 0, 8, 8))
			{
				return true;
			}
			if (array.Length == 24 && EqualBytes(array, 8, 16, 8))
			{
				return true;
			}
			return false;
		}

		private static bool EqualBytes(byte[] rgbKey, int start1, int start2, int count)
		{
			if (start1 < 0)
			{
				throw new ArgumentOutOfRangeException("start1", Environment.GetResourceString("Non-negative number required."));
			}
			if (start2 < 0)
			{
				throw new ArgumentOutOfRangeException("start2", Environment.GetResourceString("Non-negative number required."));
			}
			if (start1 + count > rgbKey.Length)
			{
				throw new ArgumentException(Environment.GetResourceString("Value was invalid."));
			}
			if (start2 + count > rgbKey.Length)
			{
				throw new ArgumentException(Environment.GetResourceString("Value was invalid."));
			}
			for (int i = 0; i < count; i++)
			{
				if (rgbKey[start1 + i] != rgbKey[start2 + i])
				{
					return false;
				}
			}
			return true;
		}

		private static bool IsLegalKeySize(byte[] rgbKey)
		{
			if (rgbKey != null && (rgbKey.Length == 16 || rgbKey.Length == 24))
			{
				return true;
			}
			return false;
		}
	}
	[ComVisible(true)]
	public sealed class TripleDESCryptoServiceProvider : TripleDES
	{
		[SecuritySafeCritical]
		public TripleDESCryptoServiceProvider()
		{
			if (!Utils.HasAlgorithm(26115, 0))
			{
				throw new CryptographicException(Environment.GetResourceString("Cryptographic service provider (CSP) could not be found for this algorithm."));
			}
			FeedbackSizeValue = 8;
		}

		[SecuritySafeCritical]
		public override ICryptoTransform CreateEncryptor(byte[] rgbKey, byte[] rgbIV)
		{
			if (TripleDES.IsWeakKey(rgbKey))
			{
				throw new CryptographicException(Environment.GetResourceString("Specified key is a known weak key for '{0}' and cannot be used."), "TripleDES");
			}
			return new TripleDESTransform(this, encryption: true, rgbKey, rgbIV);
		}

		[SecuritySafeCritical]
		public override ICryptoTransform CreateDecryptor(byte[] rgbKey, byte[] rgbIV)
		{
			if (TripleDES.IsWeakKey(rgbKey))
			{
				throw new CryptographicException(Environment.GetResourceString("Specified key is a known weak key for '{0}' and cannot be used."), "TripleDES");
			}
			return new TripleDESTransform(this, encryption: false, rgbKey, rgbIV);
		}

		public override void GenerateKey()
		{
			KeyValue = new byte[KeySizeValue / 8];
			Utils.StaticRandomNumberGenerator.GetBytes(KeyValue);
			while (TripleDES.IsWeakKey(KeyValue))
			{
				Utils.StaticRandomNumberGenerator.GetBytes(KeyValue);
			}
		}

		public override void GenerateIV()
		{
			IVValue = new byte[8];
			Utils.StaticRandomNumberGenerator.GetBytes(IVValue);
		}
	}
