			long num = x;
			int num2 = 1;
			while (num > 127)
			{
				num >>= 7;
				num2++;
			}
			byte[] array = new byte[num2];
			for (int i = 0; i < num2; i++)
			{
				num = x >> 7 * i;
				num &= 0x7F;
				if (i != 0)
				{
					num += 128;
				}
				array[num2 - i - 1] = Convert.ToByte(num);
			}
			return array;
		}
