		internal DESTransform(SymmetricAlgorithm symmAlgo, bool encryption, byte[] key, byte[] iv)
			: base(symmAlgo, encryption, iv)
		{
			byte[] array = null;
			if (key == null)
			{
				key = GetStrongKey();
				array = key;
			}
			if (DES.IsWeakKey(key) || DES.IsSemiWeakKey(key))
			{
				throw new CryptographicException(Locale.GetText("This is a known weak, or semi-weak, key."));
			}
			if (array == null)
			{
				array = (byte[])key.Clone();
			}
			keySchedule = new byte[KEY_BYTE_SIZE * 16];
			byteBuff = new byte[BLOCK_BYTE_SIZE];
			dwordBuff = new uint[BLOCK_BYTE_SIZE / 4];
			SetKey(array);
		}

		private uint CipherFunct(uint r, int n)
		{
			byte[] array = keySchedule;
			int num = n << 3;
			uint num2 = (r >> 1) | (r << 31);
			uint num3 = 0 | spBoxes[((num2 >> 26) ^ array[num++]) & 0x3F] | spBoxes[64 + (((num2 >> 22) ^ array[num++]) & 0x3F)] | spBoxes[128 + (((num2 >> 18) ^ array[num++]) & 0x3F)] | spBoxes[192 + (((num2 >> 14) ^ array[num++]) & 0x3F)] | spBoxes[256 + (((num2 >> 10) ^ array[num++]) & 0x3F)] | spBoxes[320 + (((num2 >> 6) ^ array[num++]) & 0x3F)] | spBoxes[384 + (((num2 >> 2) ^ array[num++]) & 0x3F)];
			num2 = (r << 1) | (r >> 31);
			return num3 | spBoxes[448 + ((num2 ^ array[num]) & 0x3F)];
		}

		internal static void Permutation(byte[] input, byte[] output, uint[] permTab, bool preSwap)
		{
			if (preSwap && BitConverter.IsLittleEndian)
			{
				BSwap(input);
			}
			int num = input[0] >> 4 << 1;
			int num2 = 32 + ((input[0] & 0xF) << 1);
			uint num3 = permTab[num++] | permTab[num2++];
			uint num4 = permTab[num] | permTab[num2];
			int num5 = BLOCK_BYTE_SIZE << 1;
			int num6 = 2;
			int num7 = 1;
			while (num6 < num5)
			{
				int num8 = input[num7];
				num = (num6 << 5) + (num8 >> 4 << 1);
				num2 = (num6 + 1 << 5) + ((num8 & 0xF) << 1);
				num3 |= permTab[num++] | permTab[num2++];
				num4 |= permTab[num] | permTab[num2];
				num6 += 2;
				num7++;
			}
			if (preSwap || !BitConverter.IsLittleEndian)
			{
				output[0] = (byte)num3;
				output[1] = (byte)(num3 >> 8);
				output[2] = (byte)(num3 >> 16);
				output[3] = (byte)(num3 >> 24);
				output[4] = (byte)num4;
				output[5] = (byte)(num4 >> 8);
				output[6] = (byte)(num4 >> 16);
				output[7] = (byte)(num4 >> 24);
			}
			else
			{
				output[0] = (byte)(num3 >> 24);
				output[1] = (byte)(num3 >> 16);
				output[2] = (byte)(num3 >> 8);
				output[3] = (byte)num3;
				output[4] = (byte)(num4 >> 24);
				output[5] = (byte)(num4 >> 16);
				output[6] = (byte)(num4 >> 8);
				output[7] = (byte)num4;
			}
		}

		private static void BSwap(byte[] byteBuff)
		{
			byte b = byteBuff[0];
			byteBuff[0] = byteBuff[3];
			byteBuff[3] = b;
			b = byteBuff[1];
			byteBuff[1] = byteBuff[2];
			byteBuff[2] = b;
			b = byteBuff[4];
			byteBuff[4] = byteBuff[7];
			byteBuff[7] = b;
			b = byteBuff[5];
			byteBuff[5] = byteBuff[6];
			byteBuff[6] = b;
		}

		internal void SetKey(byte[] key)
		{
			Array.Clear(keySchedule, 0, keySchedule.Length);
			int num = PC1.Length;
			byte[] array = new byte[num];
			byte[] array2 = new byte[num];
			int num2 = 0;
			byte[] pC = PC1;
			foreach (byte b in pC)
			{
				array[num2++] = (byte)((key[b >> 3] >> (7 ^ (b & 7))) & 1);
			}
			for (int j = 0; j < KEY_BYTE_SIZE * 2; j++)
			{
				int num3 = num >> 1;
				int k;
				for (k = 0; k < num3; k++)
				{
					int num4 = k + leftRotTotal[j];
					array2[k] = array[(num4 < num3) ? num4 : (num4 - num3)];
				}
				for (k = num3; k < num; k++)
				{
					int num5 = k + leftRotTotal[j];
					array2[k] = array[(num5 < num) ? num5 : (num5 - num3)];
				}
				int num6 = j * KEY_BYTE_SIZE;
				k = 0;
				pC = PC2;
				foreach (byte b2 in pC)
				{
					if (array2[b2] != 0)
					{
						keySchedule[num6 + k / 6] |= (byte)(128 >> k % 6 + 2);
					}
					k++;
				}
			}
		}

		public void ProcessBlock(byte[] input, byte[] output)
		{
			Buffer.BlockCopy(input, 0, dwordBuff, 0, BLOCK_BYTE_SIZE);
			if (encrypt)
			{
				uint num = dwordBuff[0];
				uint num2 = dwordBuff[1];
				num ^= CipherFunct(num2, 0);
				num2 ^= CipherFunct(num, 1);
				num ^= CipherFunct(num2, 2);
				num2 ^= CipherFunct(num, 3);
				num ^= CipherFunct(num2, 4);
				num2 ^= CipherFunct(num, 5);
				num ^= CipherFunct(num2, 6);
				num2 ^= CipherFunct(num, 7);
				num ^= CipherFunct(num2, 8);
				num2 ^= CipherFunct(num, 9);
				num ^= CipherFunct(num2, 10);
				num2 ^= CipherFunct(num, 11);
				num ^= CipherFunct(num2, 12);
				num2 ^= CipherFunct(num, 13);
				num ^= CipherFunct(num2, 14);
				num2 ^= CipherFunct(num, 15);
				dwordBuff[0] = num2;
				dwordBuff[1] = num;
			}
			else
			{
				uint num3 = dwordBuff[0];
				uint num4 = dwordBuff[1];
				num3 ^= CipherFunct(num4, 15);
				num4 ^= CipherFunct(num3, 14);
				num3 ^= CipherFunct(num4, 13);
				num4 ^= CipherFunct(num3, 12);
				num3 ^= CipherFunct(num4, 11);
				num4 ^= CipherFunct(num3, 10);
				num3 ^= CipherFunct(num4, 9);
				num4 ^= CipherFunct(num3, 8);
				num3 ^= CipherFunct(num4, 7);
				num4 ^= CipherFunct(num3, 6);
				num3 ^= CipherFunct(num4, 5);
				num4 ^= CipherFunct(num3, 4);
				num3 ^= CipherFunct(num4, 3);
				num4 ^= CipherFunct(num3, 2);
				num3 ^= CipherFunct(num4, 1);
				num4 ^= CipherFunct(num3, 0);
				dwordBuff[0] = num4;
				dwordBuff[1] = num3;
			}
			Buffer.BlockCopy(dwordBuff, 0, output, 0, BLOCK_BYTE_SIZE);
		}

		protected override void ECB(byte[] input, byte[] output)
		{
			Permutation(input, output, ipTab, preSwap: false);
			ProcessBlock(output, byteBuff);
			Permutation(byteBuff, output, fpTab, preSwap: true);
		}

		internal static byte[] GetStrongKey()
		{
			byte[] array = KeyBuilder.Key(KEY_BYTE_SIZE);
			while (DES.IsWeakKey(array) || DES.IsSemiWeakKey(array))
			{
				array = KeyBuilder.Key(KEY_BYTE_SIZE);
			}
			return array;
		}
	}
	[ComVisible(true)]
	public sealed class DSACryptoServiceProvider : DSA, ICspAsymmetricAlgorithm
	{
		private const int PROV_DSS_DH = 13;

		private KeyPairPersistence store;

		private bool persistKey;

		private bool persisted;

		private bool privateKeyExportable = true;

		private bool m_disposed;

		private DSAManaged dsa;

		private static bool useMachineKeyStore;

		public override string KeyExchangeAlgorithm => null;

		public override int KeySize => dsa.KeySize;

		public bool PersistKeyInCsp
		{
			get
			{
				return persistKey;
			}
			set
			{
				persistKey = value;
			}
		}

		[ComVisible(false)]
		public bool PublicOnly => dsa.PublicOnly;

		public override string SignatureAlgorithm => "http://www.w3.org/2000/09/xmldsig#dsa-sha1";

		public static bool UseMachineKeyStore
		{
			get
			{
				return useMachineKeyStore;
			}
			set
			{
				useMachineKeyStore = value;
			}
		}

		[ComVisible(false)]
		[MonoTODO("call into KeyPairPersistence to get details")]
		public CspKeyContainerInfo CspKeyContainerInfo
		{
			[SecuritySafeCritical]
			get
			{
				return null;
			}
		}

		public DSACryptoServiceProvider()
			: this(1024)
		{
		}

		public DSACryptoServiceProvider(CspParameters parameters)
			: this(1024, parameters)
		{
		}

		public DSACryptoServiceProvider(int dwKeySize)
		{
			Common(dwKeySize, parameters: false);
		}

		public DSACryptoServiceProvider(int dwKeySize, CspParameters parameters)
		{
			bool flag = parameters != null;
			Common(dwKeySize, flag);
			if (flag)
			{
				Common(parameters);
			}
		}

		private void Common(int dwKeySize, bool parameters)
		{
			LegalKeySizesValue = new KeySizes[1];
			LegalKeySizesValue[0] = new KeySizes(512, 1024, 64);
			KeySize = dwKeySize;
			dsa = new DSAManaged(dwKeySize);
			dsa.KeyGenerated += OnKeyGenerated;
			persistKey = parameters;
			if (!parameters)
			{
				CspParameters cspParameters = new CspParameters(13);
				if (useMachineKeyStore)
				{
					cspParameters.Flags |= CspProviderFlags.UseMachineKeyStore;
				}
				store = new KeyPairPersistence(cspParameters);
			}
		}

		private void Common(CspParameters parameters)
		{
			store = new KeyPairPersistence(parameters);
			store.Load();
			if (store.KeyValue != null)
			{
				persisted = true;
				FromXmlString(store.KeyValue);
			}
			privateKeyExportable = (parameters.Flags & CspProviderFlags.UseNonExportableKey) == 0;
		}

		~DSACryptoServiceProvider()
		{
			Dispose(disposing: false);
		}

		public override DSAParameters ExportParameters(bool includePrivateParameters)
		{
			if (includePrivateParameters && !privateKeyExportable)
			{
				throw new CryptographicException(Locale.GetText("Cannot export private key"));
			}
			return dsa.ExportParameters(includePrivateParameters);
		}

		public override void ImportParameters(DSAParameters parameters)
		{
			dsa.ImportParameters(parameters);
		}

		public override byte[] CreateSignature(byte[] rgbHash)
		{
			return dsa.CreateSignature(rgbHash);
		}

		public byte[] SignData(byte[] buffer)
		{
			byte[] rgbHash = SHA1.Create().ComputeHash(buffer);
			return dsa.CreateSignature(rgbHash);
		}

		public byte[] SignData(byte[] buffer, int offset, int count)
		{
			byte[] rgbHash = SHA1.Create().ComputeHash(buffer, offset, count);
			return dsa.CreateSignature(rgbHash);
		}

		public byte[] SignData(Stream inputStream)
		{
			byte[] rgbHash = SHA1.Create().ComputeHash(inputStream);
			return dsa.CreateSignature(rgbHash);
		}

		public byte[] SignHash(byte[] rgbHash, string str)
		{
			if (string.Compare(str, "SHA1", ignoreCase: true, CultureInfo.InvariantCulture) != 0)
			{
				throw new CryptographicException(Locale.GetText("Only SHA1 is supported."));
			}
			return dsa.CreateSignature(rgbHash);
		}

		public bool VerifyData(byte[] rgbData, byte[] rgbSignature)
		{
			byte[] rgbHash = SHA1.Create().ComputeHash(rgbData);
			return dsa.VerifySignature(rgbHash, rgbSignature);
		}

		public bool VerifyHash(byte[] rgbHash, string str, byte[] rgbSignature)
		{
			if (str == null)
			{
				str = "SHA1";
			}
			if (string.Compare(str, "SHA1", ignoreCase: true, CultureInfo.InvariantCulture) != 0)
			{
				throw new CryptographicException(Locale.GetText("Only SHA1 is supported."));
			}
			return dsa.VerifySignature(rgbHash, rgbSignature);
		}

		public override bool VerifySignature(byte[] rgbHash, byte[] rgbSignature)
		{
			return dsa.VerifySignature(rgbHash, rgbSignature);
		}

		protected override byte[] HashData(byte[] data, int offset, int count, HashAlgorithmName hashAlgorithm)
		{
			if (hashAlgorithm != HashAlgorithmName.SHA1)
			{
				throw new CryptographicException(Environment.GetResourceString("'{0}' is not a known hash algorithm.", hashAlgorithm.Name));
			}
			return HashAlgorithm.Create(hashAlgorithm.Name).ComputeHash(data, offset, count);
		}

		protected override byte[] HashData(Stream data, HashAlgorithmName hashAlgorithm)
		{
			if (hashAlgorithm != HashAlgorithmName.SHA1)
			{
				throw new CryptographicException(Environment.GetResourceString("'{0}' is not a known hash algorithm.", hashAlgorithm.Name));
			}
			return HashAlgorithm.Create(hashAlgorithm.Name).ComputeHash(data);
		}

		protected override void Dispose(bool disposing)
		{
			if (!m_disposed)
			{
				if (persisted && !persistKey)
				{
					store.Remove();
				}
				if (dsa != null)
				{
					dsa.Clear();
				}
				m_disposed = true;
			}
		}

		private void OnKeyGenerated(object sender, EventArgs e)
		{
			if (persistKey && !persisted)
			{
				store.KeyValue = ToXmlString(!dsa.PublicOnly);
				store.Save();
				persisted = true;
			}
		}

		[ComVisible(false)]
		[SecuritySafeCritical]
		public byte[] ExportCspBlob(bool includePrivateParameters)
		{
			byte[] array = null;
			if (includePrivateParameters)
			{
				return CryptoConvert.ToCapiPrivateKeyBlob(this);
			}
			return CryptoConvert.ToCapiPublicKeyBlob(this);
		}

		[SecuritySafeCritical]
		[ComVisible(false)]
		public void ImportCspBlob(byte[] keyBlob)
		{
			if (keyBlob == null)
			{
				throw new ArgumentNullException("keyBlob");
			}
			DSA dSA = CryptoConvert.FromCapiKeyBlobDSA(keyBlob);
			if (dSA is DSACryptoServiceProvider)
			{
				DSAParameters parameters = dSA.ExportParameters(!(dSA as DSACryptoServiceProvider).PublicOnly);
				ImportParameters(parameters);
				return;
			}
			try
			{
				DSAParameters parameters2 = dSA.ExportParameters(includePrivateParameters: true);
				ImportParameters(parameters2);
			}
			catch
			{
				DSAParameters parameters3 = dSA.ExportParameters(includePrivateParameters: false);
				ImportParameters(parameters3);
			}
		}
	}
