			fixed (byte* data2 = data)
			{
				if (_lock == null)
				{
					_handle = RngGetBytes(_handle, data2, (IntPtr)data.LongLength);
				}
				else
				{
					lock (_lock)
					{
						_handle = RngGetBytes(_handle, data2, (IntPtr)data.LongLength);
					}
				}
			}
			Check();
		}

		internal unsafe void GetBytes(byte* data, IntPtr data_length)
		{
			if (_lock == null)
			{
				_handle = RngGetBytes(_handle, data, data_length);
			}
			else
			{
				lock (_lock)
				{
					_handle = RngGetBytes(_handle, data, data_length);
				}
			}
			Check();
		}

