			}
			if ((result = GetSidSubAuthorityCount().CompareTo(sid.GetSidSubAuthorityCount())) != 0)
			{
				return result;
			}
			for (byte b = 0; b < GetSidSubAuthorityCount(); b++)
			{
				if ((result = GetSidSubAuthority(b).CompareTo(sid.GetSidSubAuthority(b))) != 0)
