	public abstract class QualifiedAce : KnownAce
	{
		private byte[] opaque;

		public AceQualifier AceQualifier
		{
			get
			{
				switch (base.AceType)
				{
				case AceType.AccessAllowed:
				case AceType.AccessAllowedCompound:
				case AceType.AccessAllowedObject:
				case AceType.AccessAllowedCallback:
				case AceType.AccessAllowedCallbackObject:
					return AceQualifier.AccessAllowed;
				case AceType.AccessDenied:
				case AceType.AccessDeniedObject:
				case AceType.AccessDeniedCallback:
				case AceType.AccessDeniedCallbackObject:
					return AceQualifier.AccessDenied;
				case AceType.SystemAlarm:
				case AceType.SystemAlarmObject:
				case AceType.SystemAlarmCallback:
				case AceType.SystemAlarmCallbackObject:
					return AceQualifier.SystemAlarm;
				case AceType.SystemAudit:
				case AceType.SystemAuditObject:
				case AceType.SystemAuditCallback:
				case AceType.SystemAuditCallbackObject:
					return AceQualifier.SystemAudit;
				default:
					throw new ArgumentException("Unrecognised ACE type: " + base.AceType);
				}
			}
		}

		public bool IsCallback
		{
			get
			{
				if (base.AceType != AceType.AccessAllowedCallback && base.AceType != AceType.AccessAllowedCallbackObject && base.AceType != AceType.AccessDeniedCallback && base.AceType != AceType.AccessDeniedCallbackObject && base.AceType != AceType.SystemAlarmCallback && base.AceType != AceType.SystemAlarmCallbackObject && base.AceType != AceType.SystemAuditCallback)
				{
					return base.AceType == AceType.SystemAuditCallbackObject;
				}
				return true;
			}
		}

		public int OpaqueLength
		{
			get
			{
				if (opaque == null)
				{
					return 0;
				}
				return opaque.Length;
			}
		}

		internal QualifiedAce(AceType type, AceFlags flags, byte[] opaque)
			: base(type, flags)
		{
			SetOpaque(opaque);
		}

		internal QualifiedAce(byte[] binaryForm, int offset)
			: base(binaryForm, offset)
		{
		}

		public byte[] GetOpaque()
		{
			if (opaque == null)
			{
				return null;
			}
			return (byte[])opaque.Clone();
		}

		public void SetOpaque(byte[] opaque)
		{
			if (opaque == null)
			{
				this.opaque = null;
			}
			else
			{
				this.opaque = (byte[])opaque.Clone();
			}
		}

		internal QualifiedAce()
		{
			ThrowStub.ThrowNotSupportedException();
		}
	}
	public sealed class RawAcl : GenericAcl
	{
		private byte revision;

		private List<GenericAce> list;

		public override int BinaryLength
		{
			get
			{
				int num = 8;
				foreach (GenericAce item in list)
				{
					num += item.BinaryLength;
				}
				return num;
			}
		}

		public override int Count => list.Count;

		public override GenericAce this[int index]
		{
			get
			{
				return list[index];
			}
			set
			{
				list[index] = value;
			}
		}

		public override byte Revision => revision;

		public RawAcl(byte revision, int capacity)
		{
			this.revision = revision;
			list = new List<GenericAce>(capacity);
		}

		public RawAcl(byte[] binaryForm, int offset)
		{
			if (binaryForm == null)
			{
				throw new ArgumentNullException("binaryForm");
			}
			if (offset < 0 || offset > binaryForm.Length - 8)
			{
				throw new ArgumentOutOfRangeException("offset", offset, "Offset out of range");
			}
			revision = binaryForm[offset];
			if (revision != GenericAcl.AclRevision && revision != GenericAcl.AclRevisionDS)
			{
				throw new ArgumentException("Invalid ACL - unknown revision", "binaryForm");
			}
			int num = ReadUShort(binaryForm, offset + 2);
			if (offset > binaryForm.Length - num)
			{
				throw new ArgumentException("Invalid ACL - truncated", "binaryForm");
			}
			int num2 = offset + 8;
			int num3 = ReadUShort(binaryForm, offset + 4);
			list = new List<GenericAce>(num3);
			for (int i = 0; i < num3; i++)
			{
				GenericAce genericAce = GenericAce.CreateFromBinaryForm(binaryForm, num2);
				list.Add(genericAce);
				num2 += genericAce.BinaryLength;
			}
		}

		internal RawAcl(byte revision, List<GenericAce> aces)
		{
			this.revision = revision;
			list = aces;
		}

		public override void GetBinaryForm(byte[] binaryForm, int offset)
		{
			if (binaryForm == null)
			{
				throw new ArgumentNullException("binaryForm");
			}
			if (offset < 0 || offset > binaryForm.Length - BinaryLength)
			{
				throw new ArgumentException("Offset out of range", "offset");
			}
			binaryForm[offset] = Revision;
			binaryForm[offset + 1] = 0;
			WriteUShort((ushort)BinaryLength, binaryForm, offset + 2);
			WriteUShort((ushort)list.Count, binaryForm, offset + 4);
			WriteUShort(0, binaryForm, offset + 6);
			int num = offset + 8;
			foreach (GenericAce item in list)
			{
				item.GetBinaryForm(binaryForm, num);
				num += item.BinaryLength;
			}
		}

		public void InsertAce(int index, GenericAce ace)
		{
			if (ace == null)
			{
				throw new ArgumentNullException("ace");
			}
			list.Insert(index, ace);
		}

		public void RemoveAce(int index)
		{
			list.RemoveAt(index);
		}

		internal override string GetSddlForm(ControlFlags sdFlags, bool isDacl)
		{
			StringBuilder stringBuilder = new StringBuilder();
			if (isDacl)
			{
				if ((sdFlags & ControlFlags.DiscretionaryAclProtected) != ControlFlags.None)
				{
					stringBuilder.Append("P");
				}
				if ((sdFlags & ControlFlags.DiscretionaryAclAutoInheritRequired) != ControlFlags.None)
				{
					stringBuilder.Append("AR");
				}
				if ((sdFlags & ControlFlags.DiscretionaryAclAutoInherited) != ControlFlags.None)
				{
					stringBuilder.Append("AI");
				}
			}
			else
			{
				if ((sdFlags & ControlFlags.SystemAclProtected) != ControlFlags.None)
				{
					stringBuilder.Append("P");
				}
				if ((sdFlags & ControlFlags.SystemAclAutoInheritRequired) != ControlFlags.None)
				{
					stringBuilder.Append("AR");
				}
				if ((sdFlags & ControlFlags.SystemAclAutoInherited) != ControlFlags.None)
				{
					stringBuilder.Append("AI");
				}
			}
			foreach (GenericAce item in list)
			{
				stringBuilder.Append(item.GetSddlForm());
			}
			return stringBuilder.ToString();
		}

		internal static RawAcl ParseSddlForm(string sddlForm, bool isDacl, ref ControlFlags sdFlags, ref int pos)
		{
			ParseFlags(sddlForm, isDacl, ref sdFlags, ref pos);
			byte b = GenericAcl.AclRevision;
			List<GenericAce> list = new List<GenericAce>();
			while (pos < sddlForm.Length && sddlForm[pos] == '(')
			{
				GenericAce genericAce = GenericAce.CreateFromSddlForm(sddlForm, ref pos);
				if (genericAce as ObjectAce != null)
				{
					b = GenericAcl.AclRevisionDS;
				}
				list.Add(genericAce);
			}
			return new RawAcl(b, list);
		}

		private static void ParseFlags(string sddlForm, bool isDacl, ref ControlFlags sdFlags, ref int pos)
		{
			char c = char.ToUpperInvariant(sddlForm[pos]);
			while (c == 'P' || c == 'A')
			{
				if (c == 'P')
				{
					if (isDacl)
					{
						sdFlags |= ControlFlags.DiscretionaryAclProtected;
					}
					else
					{
						sdFlags |= ControlFlags.SystemAclProtected;
					}
					pos++;
				}
				else
				{
					if (sddlForm.Length <= pos + 1)
					{
						throw new ArgumentException("Invalid SDDL string.", "sddlForm");
					}
					switch (char.ToUpperInvariant(sddlForm[pos + 1]))
					{
					case 'R':
						if (isDacl)
						{
							sdFlags |= ControlFlags.DiscretionaryAclAutoInheritRequired;
						}
						else
						{
							sdFlags |= ControlFlags.SystemAclAutoInheritRequired;
						}
						pos += 2;
						break;
					case 'I':
						if (isDacl)
						{
							sdFlags |= ControlFlags.DiscretionaryAclAutoInherited;
						}
						else
						{
							sdFlags |= ControlFlags.SystemAclAutoInherited;
						}
						pos += 2;
						break;
					default:
						throw new ArgumentException("Invalid SDDL string.", "sddlForm");
					}
				}
				c = char.ToUpperInvariant(sddlForm[pos]);
			}
		}

		private void WriteUShort(ushort val, byte[] buffer, int offset)
		{
			buffer[offset] = (byte)val;
			buffer[offset + 1] = (byte)(val >> 8);
		}

		private ushort ReadUShort(byte[] buffer, int offset)
		{
			return (ushort)(buffer[offset] | (buffer[offset + 1] << 8));
		}
	}
	public sealed class RawSecurityDescriptor : GenericSecurityDescriptor
	{
		private ControlFlags control_flags;

		private SecurityIdentifier owner_sid;

		private SecurityIdentifier group_sid;

		private RawAcl system_acl;

		private RawAcl discretionary_acl;

		private byte resourcemgr_control;

		public override ControlFlags ControlFlags => control_flags;

		public RawAcl DiscretionaryAcl
		{
			get
			{
				return discretionary_acl;
			}
			set
			{
				discretionary_acl = value;
			}
		}

		public override SecurityIdentifier Group
		{
			get
			{
				return group_sid;
			}
			set
			{
				group_sid = value;
			}
		}

		public override SecurityIdentifier Owner
		{
			get
			{
				return owner_sid;
			}
			set
			{
				owner_sid = value;
			}
		}

		public byte ResourceManagerControl
		{
			get
			{
				return resourcemgr_control;
			}
			set
			{
				resourcemgr_control = value;
			}
		}

		public RawAcl SystemAcl
		{
			get
			{
				return system_acl;
			}
			set
			{
				system_acl = value;
			}
		}

		internal override GenericAcl InternalDacl => DiscretionaryAcl;

		internal override GenericAcl InternalSacl => SystemAcl;

		internal override byte InternalReservedField => ResourceManagerControl;

		public RawSecurityDescriptor(string sddlForm)
		{
			if (sddlForm == null)
			{
				throw new ArgumentNullException("sddlForm");
			}
			ParseSddl(sddlForm.Replace(" ", ""));
			control_flags |= ControlFlags.SelfRelative;
		}

		public RawSecurityDescriptor(byte[] binaryForm, int offset)
		{
			if (binaryForm == null)
			{
				throw new ArgumentNullException("binaryForm");
			}
			if (offset < 0 || offset > binaryForm.Length - 20)
			{
				throw new ArgumentOutOfRangeException("offset", offset, "Offset out of range");
			}
			if (binaryForm[offset] != 1)
			{
				throw new ArgumentException("Unrecognized Security Descriptor revision.", "binaryForm");
			}
			resourcemgr_control = binaryForm[offset + 1];
			control_flags = (ControlFlags)ReadUShort(binaryForm, offset + 2);
			int num = ReadInt(binaryForm, offset + 4);
			int num2 = ReadInt(binaryForm, offset + 8);
			int num3 = ReadInt(binaryForm, offset + 12);
			int num4 = ReadInt(binaryForm, offset + 16);
			if (num != 0)
			{
				owner_sid = new SecurityIdentifier(binaryForm, num);
			}
			if (num2 != 0)
			{
				group_sid = new SecurityIdentifier(binaryForm, num2);
			}
			if (num3 != 0)
			{
				system_acl = new RawAcl(binaryForm, num3);
			}
			if (num4 != 0)
			{
				discretionary_acl = new RawAcl(binaryForm, num4);
			}
		}

		public RawSecurityDescriptor(ControlFlags flags, SecurityIdentifier owner, SecurityIdentifier group, RawAcl systemAcl, RawAcl discretionaryAcl)
		{
			control_flags = flags;
			owner_sid = owner;
			group_sid = group;
			system_acl = systemAcl;
			discretionary_acl = discretionaryAcl;
		}

		public void SetFlags(ControlFlags flags)
		{
			control_flags = flags | ControlFlags.SelfRelative;
		}

		private void ParseSddl(string sddlForm)
		{
			ControlFlags sdFlags = ControlFlags.None;
			int pos = 0;
			while (pos < sddlForm.Length - 2)
			{
				switch (sddlForm.Substring(pos, 2))
				{
				case "O:":
					pos += 2;
					Owner = SecurityIdentifier.ParseSddlForm(sddlForm, ref pos);
					break;
				case "G:":
					pos += 2;
					Group = SecurityIdentifier.ParseSddlForm(sddlForm, ref pos);
					break;
				case "D:":
					pos += 2;
					DiscretionaryAcl = RawAcl.ParseSddlForm(sddlForm, isDacl: true, ref sdFlags, ref pos);
					sdFlags |= ControlFlags.DiscretionaryAclPresent;
					break;
				case "S:":
					pos += 2;
					SystemAcl = RawAcl.ParseSddlForm(sddlForm, isDacl: false, ref sdFlags, ref pos);
					sdFlags |= ControlFlags.SystemAclPresent;
					break;
				default:
					throw new ArgumentException("Invalid SDDL.", "sddlForm");
				}
			}
			if (pos != sddlForm.Length)
			{
				throw new ArgumentException("Invalid SDDL.", "sddlForm");
			}
			SetFlags(sdFlags);
		}

		private ushort ReadUShort(byte[] buffer, int offset)
		{
			return (ushort)(buffer[offset] | (buffer[offset + 1] << 8));
		}

		private int ReadInt(byte[] buffer, int offset)
		{
			return buffer[offset] | (buffer[offset + 1] << 8) | (buffer[offset + 2] << 16) | (buffer[offset + 3] << 24);
		}
	}
