		internal static void DisposeIdentity(Identity ident)
		{
			lock (uri_hash)
			{
				if (!ident.Disposed)
				{
					if (ident is ClientIdentity clientIdentity)
					{
						uri_hash.Remove(GetNormalizedUri(clientIdentity.TargetUri));
					}
					else
					{
						uri_hash.Remove(ident.ObjectUri);
					}
					ident.Disposed = true;
				}
			}
		}

