		[SecurityCritical]
		public object Pop(IClientChannelSink sink)
		{
			while (_sinkStack != null)
			{
				ChanelSinkStackEntry sinkStack = _sinkStack;
				_sinkStack = _sinkStack.Next;
				if (sinkStack.Sink == sink)
