			int num = 0;
			if (value[0] == '-')
			{
				num = 1;
			}
			bool flag = num == 1;
			if (value[num] != 'P')
			{
				throw new ArgumentException("Invalid format string for duration schema datatype.");
			}
			num++;
			int num2 = 0;
			int num3 = 0;
			bool flag2 = false;
			int hours = 0;
			int minutes = 0;
			double value2 = 0.0;
			bool flag3 = false;
			int i = num;
			while (i < value.Length)
			{
				if (value[i] == 'T')
				{
					flag2 = true;
					num2 = 4;
					i++;
					num = i;
					continue;
				}
				bool flag4 = true;
				int num4 = 0;
				for (; i < value.Length; i++)
				{
					if (!char.IsDigit(value[i]))
					{
						if (value[i] != '.')
