				binaryObjectWithMapTyped = new BinaryObjectWithMapTyped();
			}
			assemId = (int)typeNameInfo.NIassemId;
			binaryObjectWithMapTyped.Set(num, text, numMembers, memberNames, array, array2, array3, assemId);
