			}
			type = ((!isTyped) ? memberTypesList[num] : cache.memberTypes[num]);
			if ((object)type == null)
			{
				throw new SerializationException(Environment.GetResourceString("Types not available for ISerializable object '{0}'.", objectType?.ToString() + " " + name));
			}
			return type;
		}

