					if (num2 == 4)
					{
						return true;
					}
				}
				switch (publicKey[0])
				{
				case 0:
					if (publicKey.Length > 12 && publicKey[12] == 6)
					{
						return CryptoConvert.TryImportCapiPublicKeyBlob(publicKey, 12);
					}
					break;
				case 6:
					return CryptoConvert.TryImportCapiPublicKeyBlob(publicKey, 0);
				}
				return false;
			}
