				cspParameters.KeyContainerName = _keyPairContainer;
				_rsa = new RSACryptoServiceProvider(cspParameters);
			}
			return _rsa;
		}

		private void LoadKey(byte[] key)
		{
			try
			{
				if (key.Length == 16)
				{
					int num = 0;
					int num2 = 0;
					while (num < key.Length)
					{
						num2 += key[num++];
					}
					if (num2 == 4)
