			}
			if (modules == null)
			{
				return null;
			}
			ModuleBuilder[] array = modules;
			foreach (Module module in array)
			{
				if (module.ScopeName == name)
				{
					return module;
				}
			}
			return null;
		}

		public override Module[] GetModules(bool getResourceModules)
		{
