			if (!getResourceModules)
			{
				List<Module> list = new List<Module>(modulesInternal.Length);
				Module[] array = modulesInternal;
				foreach (Module module in array)
				{
					if (!module.IsResource())
					{
						list.Add(module);
					}
				}
				return list.ToArray();
			}
			return modulesInternal;
		}

