		internal ILGenerator(Module m, TokenGenerator token_gen, int size)
		{
			if (size < 0)
			{
				size = 128;
			}
			code = new byte[size];
			token_fixups = new ILTokenInfo[8];
			module = m;
			this.token_gen = token_gen;
