			ll_emit(opcode);
			if (field.DeclaringType.Module == module || field is FieldOnTypeBuilderInst || field is FieldBuilder)
			{
				add_token_fixup(field);
			}
			emit_int(token);
		}

		public virtual void Emit(OpCode opcode, short arg)
		{
			make_room(4);
			ll_emit(opcode);
