		{
			SignatureHelper methodSigHelper = SignatureHelper.GetMethodSigHelper(module as ModuleBuilder, (CallingConventions)0, unmanagedCallConv, returnType, parameterTypes);
			Emit(opcode, methodSigHelper);
		}

