			pop = (byte)((p >> 24) & 0xFF);
			size = (byte)(q & 0xFF);
			type = (byte)((q >> 8) & 0xFF);
			args = (byte)((q >> 16) & 0xFF);
			flow = (byte)((q >> 24) & 0xFF);
		}

