		internal ParameterBuilder(MethodBase mb, int pos, ParameterAttributes attributes, string strParamName)
		{
			name = strParamName;
			position = pos;
			attrs = attributes;
			methodb = mb;
			if (mb is DynamicMethod)
			{
				table_idx = 0;
			}
			else
			{
				table_idx = mb.get_next_table_index(this, 8, 1);
			}
