		internal static int InternalConvertToUtf32(string s, int index)
		{
			if (index < s.Length - 1)
			{
				int num = s[index] - 55296;
				if ((uint)num <= 1023u)
				{
					int num2 = s[index + 1] - 56320;
					if ((uint)num2 <= 1023u)
					{
						return num * 1024 + num2 + 65536;
					}
				}
			}
			return s[index];
		}

