		}

		public static bool operator ==(SortVersion left, SortVersion right)
		{
			return left?.Equals(right) ?? right?.Equals(left) ?? true;
		}

		public static bool operator !=(SortVersion left, SortVersion right)
		{
			return !(left == right);
		}
	}
