			internal TimeSpanToken GetNextToken()
			{
				int pos = _pos;
				if (pos >= _value.Length)
				{
					return new TimeSpanToken(TTT.End);
				}
				int num = _value[pos] - 48;
				if ((uint)num <= 9u)
				{
					int num2 = 0;
					if (num == 0)
