		{
			if (!IsLeapYear(year, era))
			{
				return 0;
			}
			int monthsInYear = GetMonthsInYear(year, era);
			for (int i = 1; i <= monthsInYear; i++)
			{
				if (IsLeapMonth(year, i, era))
				{
					return i;
				}
			}
			return 0;
		}

