			int num3 = num / 365;
			if (num3 == 4)
			{
				num3 = 3;
			}
			if (part == 0)
			{
				return num2 * 4 + num3 + 1;
			}
			num -= num3 * 365;
			if (part == 1)
			{
				return num + 1;
			}
			int[] array = ((num3 == 3) ? DaysToMonth366 : DaysToMonth365);
			int i;
			for (i = num >> 6; num >= array[i]; i++)
			{
			}
			if (part == 2)
