			int[] array = ((year % 4 == 0) ? DaysToMonth366 : DaysToMonth365);
			return array[month] - array[month - 1];
		}

		public override int GetDaysInYear(int year, int era)
		{
			if (!IsLeapYear(year, era))
			{
				return 365;
			}
			return 366;
		}

		public override int GetEra(DateTime time)
		{
			return JulianEra;
		}

		public override int GetMonth(DateTime time)
		{
			return GetDatePart(time.Ticks, 2);
		}

		public override int GetMonthsInYear(int year, int era)
		{
			CheckYearEraRange(year, era);
			return 12;
		}

		public override int GetYear(DateTime time)
		{
			return GetDatePart(time.Ticks, 0);
		}

		public override bool IsLeapDay(int year, int month, int day, int era)
		{
			CheckMonthRange(month);
			if (IsLeapYear(year, era))
			{
				CheckDayRange(year, month, day);
				if (month == 2)
				{
					return day == 29;
				}
				return false;
			}
			CheckDayRange(year, month, day);
			return false;
		}

		[ComVisible(false)]
		public override int GetLeapMonth(int year, int era)
		{
			CheckYearEraRange(year, era);
			return 0;
		}

		public override bool IsLeapMonth(int year, int month, int era)
		{
			CheckYearEraRange(year, era);
			CheckMonthRange(month);
			return false;
		}

		public override bool IsLeapYear(int year, int era)
		{
			CheckYearEraRange(year, era);
			return year % 4 == 0;
		}

		public override DateTime ToDateTime(int year, int month, int day, int hour, int minute, int second, int millisecond, int era)
		{
			CheckYearEraRange(year, era);
			CheckMonthRange(month);
			CheckDayRange(year, month, day);
			if (millisecond < 0 || millisecond >= 1000)
			{
				throw new ArgumentOutOfRangeException("millisecond", string.Format(CultureInfo.CurrentCulture, Environment.GetResourceString("Valid values are between {0} and {1}, inclusive."), 0, 999));
			}
			if (hour >= 0 && hour < 24 && minute >= 0 && minute < 60 && second >= 0 && second < 60)
			{
				return new DateTime(DateToTicks(year, month, day) + new TimeSpan(0, hour, minute, second, millisecond).Ticks);
			}
			throw new ArgumentOutOfRangeException(null, Environment.GetResourceString("Hour, Minute, and Second parameters describe an un-representable DateTime."));
		}

		public override int ToFourDigitYear(int year)
		{
			if (year < 0)
			{
				throw new ArgumentOutOfRangeException("year", Environment.GetResourceString("Non-negative number required."));
			}
			if (year > MaxYear)
			{
				throw new ArgumentOutOfRangeException("year", string.Format(CultureInfo.CurrentCulture, Environment.GetResourceString("Argument must be between {0} and {1}."), 1, MaxYear));
			}
			return base.ToFourDigitYear(year);
		}
	}
	[Serializable]
	[ComVisible(true)]
	public class KoreanCalendar : Calendar
	{
		public const int KoreanEra = 1;

		internal static EraInfo[] koreanEraInfo = new EraInfo[1]
		{
			new EraInfo(1, 1, 1, 1, -2333, 2334, 12332)
		};

		internal GregorianCalendarHelper helper;

		private const int DEFAULT_TWO_DIGIT_YEAR_MAX = 4362;

		[ComVisible(false)]
		public override DateTime MinSupportedDateTime => DateTime.MinValue;

		[ComVisible(false)]
		public override DateTime MaxSupportedDateTime => DateTime.MaxValue;

		[ComVisible(false)]
		public override CalendarAlgorithmType AlgorithmType => CalendarAlgorithmType.SolarCalendar;

		internal override int ID => 5;

		public override int[] Eras => helper.Eras;

		public override int TwoDigitYearMax
		{
			get
			{
				if (twoDigitYearMax == -1)
				{
					twoDigitYearMax = Calendar.GetSystemTwoDigitYearSetting(ID, 4362);
				}
				return twoDigitYearMax;
			}
			set
			{
				VerifyWritable();
				if (value < 99 || value > helper.MaxYear)
				{
					throw new ArgumentOutOfRangeException("year", string.Format(CultureInfo.CurrentCulture, Environment.GetResourceString("Valid values are between {0} and {1}, inclusive."), 99, helper.MaxYear));
				}
				twoDigitYearMax = value;
			}
		}

		public KoreanCalendar()
		{
			try
			{
				new CultureInfo("ko-KR");
			}
			catch (ArgumentException innerException)
			{
				throw new TypeInitializationException(GetType().FullName, innerException);
			}
			helper = new GregorianCalendarHelper(this, koreanEraInfo);
		}

		public override DateTime AddMonths(DateTime time, int months)
		{
			return helper.AddMonths(time, months);
		}

		public override DateTime AddYears(DateTime time, int years)
		{
			return helper.AddYears(time, years);
		}

		public override int GetDaysInMonth(int year, int month, int era)
		{
			return helper.GetDaysInMonth(year, month, era);
		}

		public override int GetDaysInYear(int year, int era)
		{
			return helper.GetDaysInYear(year, era);
		}

		public override int GetDayOfMonth(DateTime time)
		{
			return helper.GetDayOfMonth(time);
		}

		public override DayOfWeek GetDayOfWeek(DateTime time)
		{
			return helper.GetDayOfWeek(time);
		}

		public override int GetDayOfYear(DateTime time)
		{
			return helper.GetDayOfYear(time);
		}

		public override int GetMonthsInYear(int year, int era)
		{
			return helper.GetMonthsInYear(year, era);
		}

		[ComVisible(false)]
		public override int GetWeekOfYear(DateTime time, CalendarWeekRule rule, DayOfWeek firstDayOfWeek)
		{
			return helper.GetWeekOfYear(time, rule, firstDayOfWeek);
		}

		public override int GetEra(DateTime time)
		{
			return helper.GetEra(time);
		}

		public override int GetMonth(DateTime time)
		{
			return helper.GetMonth(time);
		}

		public override int GetYear(DateTime time)
		{
			return helper.GetYear(time);
		}

		public override bool IsLeapDay(int year, int month, int day, int era)
		{
			return helper.IsLeapDay(year, month, day, era);
		}

		public override bool IsLeapYear(int year, int era)
		{
			return helper.IsLeapYear(year, era);
		}

		[ComVisible(false)]
		public override int GetLeapMonth(int year, int era)
		{
			return helper.GetLeapMonth(year, era);
		}

		public override bool IsLeapMonth(int year, int month, int era)
		{
			return helper.IsLeapMonth(year, month, era);
		}

		public override DateTime ToDateTime(int year, int month, int day, int hour, int minute, int second, int millisecond, int era)
		{
			return helper.ToDateTime(year, month, day, hour, minute, second, millisecond, era);
		}

		public override int ToFourDigitYear(int year)
		{
			if (year < 0)
			{
				throw new ArgumentOutOfRangeException("year", Environment.GetResourceString("Non-negative number required."));
			}
			return helper.ToFourDigitYear(year, TwoDigitYearMax);
		}
	}
