		public override DateTime MinSupportedDateTime => minDate;

		public override DateTime MaxSupportedDateTime => maxDate;

		protected override int DaysInYearBeforeMinSupportedYear => 384;

		internal override int MinCalendarYear => 918;

		internal override int MaxCalendarYear => 2050;

		internal override DateTime MinDate => minDate;

		internal override DateTime MaxDate => maxDate;

		internal override EraInfo[] CalEraInfo => null;

		internal override int BaseCalendarID => 5;

		internal override int ID => 20;

		public override int[] Eras => new int[1] { 1 };

		internal override int GetYearInfo(int LunarYear, int Index)
		{
			if (LunarYear < 918 || LunarYear > 2050)
			{
				throw new ArgumentOutOfRangeException("year", string.Format(CultureInfo.CurrentCulture, Environment.GetResourceString("Valid values are between {0} and {1}, inclusive."), 918, 2050));
			}
			return yinfo[LunarYear - 918, Index];
		}

		internal override int GetYear(int year, DateTime time)
		{
			return year;
		}

		internal override int GetGregorianYear(int year, int era)
		{
			if (era != 0 && era != 1)
			{
				throw new ArgumentOutOfRangeException("era", Environment.GetResourceString("Era value was not valid."));
			}
			if (year < 918 || year > 2050)
			{
				throw new ArgumentOutOfRangeException("year", string.Format(CultureInfo.CurrentCulture, Environment.GetResourceString("Valid values are between {0} and {1}, inclusive."), 918, 2050));
			}
			return year;
		}

		public override int GetEra(DateTime time)
		{
			CheckTicksRange(time.Ticks);
			return 1;
		}
	}
