					num = (num << 5) - num + char.ToUpperInvariant(*ptr2);
					num = (num << 5) - num + char.ToUpperInvariant(ptr2[1]);
				}
				ptr3++;
				if (ptr2 < ptr3)
				{
					num = (num << 5) - num + char.ToUpperInvariant(*ptr2);
				}
				return num;
			}
		}

