			return false;
		}

		public override int GetHashCode()
		{
			if (key.Length == 0)
			{
				return 0;
			}
			int num = key[0];
			for (int i = 1; i < key.Length; i++)
			{
				num ^= key[i] << (i & 3);
			}
			return num;
		}

