			}
			textInfo = TextInfo.Invariant;
			m_name = string.Empty;
			englishname = (nativename = "Invariant Language (Invariant Country)");
			iso3lang = "IVL";
			iso2lang = "iv";
			win3lang = "IVL";
			default_calendar_type = 257;
