		private static Calendar CreateCalendar(int calendarType)
		{
			string text = null;
			switch (calendarType >> 8)
			{
			case 1:
				return new GregorianCalendar((GregorianCalendarTypes)(calendarType & 0xFF));
			case 2:
				text = "System.Globalization.ThaiBuddhistCalendar";
				break;
			case 3:
				text = "System.Globalization.UmAlQuraCalendar";
				break;
			case 4:
				text = "System.Globalization.HijriCalendar";
				break;
			default:
				throw new NotImplementedException("Unknown calendar type: " + calendarType);
			}
			Type type = Type.GetType(text, throwOnError: false);
			if (type == null)
			{
				return new GregorianCalendar(GregorianCalendarTypes.Localized);
			}
			return (Calendar)Activator.CreateInstance(type);
		}

		private static Exception CreateNotFoundException(string name)
		{
			return new CultureNotFoundException("name", "Culture name " + name + " is not supported.");
		}

		[DllImport("__Internal")]
		private static extern void InitializeUserPreferredCultureInfoInAppX(OnCultureInfoChangedDelegate onCultureInfoChangedInAppX);

		[DllImport("__Internal")]
		private static extern void SetUserPreferredCultureInfoInAppX([MarshalAs(UnmanagedType.LPWStr)] string name);

		[MonoPInvokeCallback(typeof(OnCultureInfoChangedDelegate))]
		private static void OnCultureInfoChangedInAppX([MarshalAs(UnmanagedType.LPWStr)] string language)
		{
			if (language != null)
			{
				s_UserPreferredCultureInfoInAppX = new CultureInfo(language);
			}
			else
			{
				s_UserPreferredCultureInfoInAppX = null;
			}
		}

		internal static CultureInfo GetCultureInfoForUserPreferredLanguageInAppX()
		{
			if (s_UserPreferredCultureInfoInAppX == null)
			{
				InitializeUserPreferredCultureInfoInAppX(OnCultureInfoChangedInAppX);
			}
			return s_UserPreferredCultureInfoInAppX;
		}

		internal static void SetCultureInfoForUserPreferredLanguageInAppX(CultureInfo cultureInfo)
		{
			if (s_UserPreferredCultureInfoInAppX == null)
			{
				InitializeUserPreferredCultureInfoInAppX(OnCultureInfoChangedInAppX);
			}
			SetUserPreferredCultureInfoInAppX(cultureInfo.Name);
			s_UserPreferredCultureInfoInAppX = cultureInfo;
		}

		internal static void CheckDomainSafetyObject(object obj, object container)
		{
			if (obj.GetType().Assembly != typeof(CultureInfo).Assembly)
			{
				throw new InvalidOperationException(string.Format(CurrentCulture, Environment.GetResourceString("Cannot set sub-classed {0} object to {1} object."), obj.GetType(), container.GetType()));
			}
		}

		internal static bool VerifyCultureName(string cultureName, bool throwException)
		{
			foreach (char c in cultureName)
			{
				if (!char.IsLetterOrDigit(c) && c != '-' && c != '_')
				{
					if (throwException)
					{
						throw new ArgumentException(Environment.GetResourceString("The given culture name '{0}' cannot be used to locate a resource file. Resource filenames must consist of only letters, numbers, hyphens or underscores.", cultureName));
					}
					return false;
				}
			}
			return true;
		}

		internal static bool VerifyCultureName(CultureInfo culture, bool throwException)
		{
			if (!culture.m_isInherited)
			{
				return true;
			}
			return VerifyCultureName(culture.Name, throwException);
		}
	}
	public sealed class IdnMapping
	{
		private bool allow_unassigned;

		private bool use_std3;

		private Punycode puny = new Punycode();

		public bool AllowUnassigned
		{
			get
			{
				return allow_unassigned;
			}
			set
			{
				allow_unassigned = value;
			}
		}

		public bool UseStd3AsciiRules
		{
			get
			{
				return use_std3;
			}
			set
			{
				use_std3 = value;
			}
		}

		public override bool Equals(object obj)
		{
			if (obj is IdnMapping idnMapping && allow_unassigned == idnMapping.allow_unassigned)
			{
				return use_std3 == idnMapping.use_std3;
			}
			return false;
		}

		public override int GetHashCode()
		{
			return (allow_unassigned ? 2 : 0) + (use_std3 ? 1 : 0);
		}

		public string GetAscii(string unicode)
		{
			if (unicode == null)
			{
				throw new ArgumentNullException("unicode");
			}
			return GetAscii(unicode, 0, unicode.Length);
		}

		public string GetAscii(string unicode, int index)
		{
			if (unicode == null)
			{
				throw new ArgumentNullException("unicode");
			}
			return GetAscii(unicode, index, unicode.Length - index);
		}

		public string GetAscii(string unicode, int index, int count)
		{
			if (unicode == null)
			{
				throw new ArgumentNullException("unicode");
			}
			if (index < 0)
			{
				throw new ArgumentOutOfRangeException("index must be non-negative value");
			}
			if (count < 0 || index + count > unicode.Length)
			{
				throw new ArgumentOutOfRangeException("index + count must point inside the argument unicode string");
			}
			return Convert(unicode, index, count, toAscii: true);
		}

		private string Convert(string input, int index, int count, bool toAscii)
		{
			string text = input.Substring(index, count);
			for (int i = 0; i < text.Length; i++)
			{
				if (text[i] >= '\u0080')
				{
					text = text.ToLower(CultureInfo.InvariantCulture);
					break;
				}
			}
			string[] array = text.Split('.', '。', '．', '｡');
			int num = 0;
			for (int j = 0; j < array.Length; j++)
			{
				if (array[j].Length != 0 || j + 1 != array.Length)
				{
					if (toAscii)
					{
						array[j] = ToAscii(array[j], num);
					}
					else
					{
						array[j] = ToUnicode(array[j], num);
					}
				}
				num += array[j].Length;
			}
			return string.Join(".", array);
		}

		private string ToAscii(string s, int offset)
		{
			for (int i = 0; i < s.Length; i++)
			{
				if (s[i] < ' ' || s[i] == '\u007f')
				{
					throw new ArgumentException($"Not allowed character was found, at {offset + i}");
				}
				if (s[i] >= '\u0080')
				{
					s = NamePrep(s, offset);
					break;
				}
			}
			if (use_std3)
			{
				VerifyStd3AsciiRules(s, offset);
			}
			for (int j = 0; j < s.Length; j++)
			{
				if (s[j] >= '\u0080')
				{
					if (s.StartsWith("xn--", StringComparison.OrdinalIgnoreCase))
					{
						throw new ArgumentException($"The input string must not start with ACE (xn--), at {offset + j}");
					}
					s = puny.Encode(s, offset);
					s = "xn--" + s;
					break;
				}
			}
			VerifyLength(s, offset);
			return s;
		}

		private void VerifyLength(string s, int offset)
		{
			if (s.Length == 0)
			{
				throw new ArgumentException($"A label in the input string resulted in an invalid zero-length string, at {offset}");
			}
			if (s.Length > 63)
			{
				throw new ArgumentException($"A label in the input string exceeded the length in ASCII representation, at {offset}");
			}
		}

		private string NamePrep(string s, int offset)
		{
			s = s.Normalize(NormalizationForm.FormKC);
			VerifyProhibitedCharacters(s, offset);
			if (!allow_unassigned)
			{
				for (int i = 0; i < s.Length; i++)
				{
					if (char.GetUnicodeCategory(s, i) == UnicodeCategory.OtherNotAssigned)
					{
						throw new ArgumentException($"Use of unassigned Unicode characer is prohibited in this IdnMapping, at {offset + i}");
					}
				}
			}
			return s;
		}

		private void VerifyProhibitedCharacters(string s, int offset)
		{
			for (int i = 0; i < s.Length; i++)
			{
				switch (char.GetUnicodeCategory(s, i))
				{
				case UnicodeCategory.SpaceSeparator:
					if (s[i] < '\u0080')
					{
						continue;
					}
					break;
				case UnicodeCategory.Control:
					if (s[i] != 0 && s[i] < '\u0080')
					{
						continue;
					}
					break;
				default:
				{
					char c = s[i];
					if (('\ufddf' > c || c > '\ufdef') && (c & 0xFFFF) != 65534 && ('\ufff9' > c || c > '\ufffd') && ('⿰' > c || c > '⿻') && ('\u202a' > c || c > '\u202e') && ('\u206a' > c || c > '\u206f'))
					{
						switch (c)
						{
						case '\u0340':
						case '\u0341':
						case '\u200e':
						case '\u200f':
						case '\u2028':
						case '\u2029':
							break;
						default:
							continue;
						}
					}
					break;
				}
				case UnicodeCategory.Surrogate:
				case UnicodeCategory.PrivateUse:
					break;
				}
				throw new ArgumentException($"Not allowed character was in the input string, at {offset + i}");
			}
		}

		private void VerifyStd3AsciiRules(string s, int offset)
		{
			if (s.Length > 0 && s[0] == '-')
			{
				throw new ArgumentException($"'-' is not allowed at head of a sequence in STD3 mode, found at {offset}");
			}
			if (s.Length > 0 && s[s.Length - 1] == '-')
			{
				throw new ArgumentException($"'-' is not allowed at tail of a sequence in STD3 mode, found at {offset + s.Length - 1}");
			}
			for (int i = 0; i < s.Length; i++)
			{
				char c = s[i];
				if (c != '-' && (c <= '/' || (':' <= c && c <= '@') || ('[' <= c && c <= '`') || ('{' <= c && c <= '\u007f')))
				{
					throw new ArgumentException($"Not allowed character in STD3 mode, found at {offset + i}");
				}
			}
		}

		public string GetUnicode(string ascii)
		{
			if (ascii == null)
			{
				throw new ArgumentNullException("ascii");
			}
			return GetUnicode(ascii, 0, ascii.Length);
		}

		public string GetUnicode(string ascii, int index)
		{
			if (ascii == null)
			{
				throw new ArgumentNullException("ascii");
			}
			return GetUnicode(ascii, index, ascii.Length - index);
		}

		public string GetUnicode(string ascii, int index, int count)
		{
			if (ascii == null)
			{
				throw new ArgumentNullException("ascii");
			}
			if (index < 0)
			{
				throw new ArgumentOutOfRangeException("index must be non-negative value");
			}
			if (count < 0 || index + count > ascii.Length)
			{
				throw new ArgumentOutOfRangeException("index + count must point inside the argument ascii string");
			}
			return Convert(ascii, index, count, toAscii: false);
		}

		private string ToUnicode(string s, int offset)
		{
			for (int i = 0; i < s.Length; i++)
			{
				if (s[i] >= '\u0080')
				{
					s = NamePrep(s, offset);
					break;
				}
			}
			if (!s.StartsWith("xn--", StringComparison.OrdinalIgnoreCase))
			{
				return s;
			}
			s = s.ToLower(CultureInfo.InvariantCulture);
			string strA = s;
			s = s.Substring(4);
			s = puny.Decode(s, offset);
			string result = s;
			s = ToAscii(s, offset);
			if (string.Compare(strA, s, StringComparison.OrdinalIgnoreCase) != 0)
			{
				throw new ArgumentException($"ToUnicode() failed at verifying the result, at label part from {offset}");
			}
			return result;
		}
	}
	internal class Bootstring
	{
		private readonly char delimiter;

		private readonly int base_num;

		private readonly int tmin;

		private readonly int tmax;

		private readonly int skew;

		private readonly int damp;

		private readonly int initial_bias;

		private readonly int initial_n;

		public Bootstring(char delimiter, int baseNum, int tmin, int tmax, int skew, int damp, int initialBias, int initialN)
		{
			this.delimiter = delimiter;
			base_num = baseNum;
			this.tmin = tmin;
			this.tmax = tmax;
			this.skew = skew;
			this.damp = damp;
			initial_bias = initialBias;
			initial_n = initialN;
		}

		public string Encode(string s, int offset)
		{
			int num = initial_n;
			int num2 = 0;
			int num3 = initial_bias;
			int num4 = 0;
			int num5 = 0;
			StringBuilder stringBuilder = new StringBuilder();
			for (int i = 0; i < s.Length; i++)
			{
				if (s[i] < '\u0080')
				{
					stringBuilder.Append(s[i]);
				}
			}
			num4 = (num5 = stringBuilder.Length);
			if (num4 > 0)
			{
				stringBuilder.Append(delimiter);
			}
			while (num5 < s.Length)
			{
				int num6 = int.MaxValue;
				for (int j = 0; j < s.Length; j++)
				{
					if (s[j] >= num && s[j] < num6)
					{
						num6 = s[j];
					}
				}
				num2 = checked(num2 + (num6 - num) * (num5 + 1));
				num = num6;
				foreach (char c in s)
				{
					if (c < num || c < '\u0080')
					{
						num2 = checked(num2 + 1);
					}
					if (c != num)
					{
						continue;
					}
					int num7 = num2;
					int num8 = base_num;
					while (true)
					{
						int num9 = ((num8 <= num3 + tmin) ? tmin : ((num8 >= num3 + tmax) ? tmax : (num8 - num3)));
						if (num7 < num9)
						{
							break;
						}
						stringBuilder.Append(EncodeDigit(num9 + (num7 - num9) % (base_num - num9)));
						num7 = (num7 - num9) / (base_num - num9);
						num8 += base_num;
					}
					stringBuilder.Append(EncodeDigit(num7));
					num3 = Adapt(num2, num5 + 1, num5 == num4);
					num2 = 0;
					num5++;
				}
				num2++;
				num++;
			}
			return stringBuilder.ToString();
		}

		private char EncodeDigit(int d)
		{
			return (char)((d < 26) ? (d + 97) : (d - 26 + 48));
		}

		private int DecodeDigit(char c)
		{
			if (c - 48 >= 10)
			{
				if (c - 65 >= 26)
				{
					if (c - 97 >= 26)
					{
						return base_num;
					}
					return c - 97;
				}
				return c - 65;
			}
			return c - 22;
		}

		private int Adapt(int delta, int numPoints, bool firstTime)
		{
			delta = ((!firstTime) ? (delta / 2) : (delta / damp));
			delta += delta / numPoints;
			int num = 0;
			while (delta > (base_num - tmin) * tmax / 2)
			{
				delta /= base_num - tmin;
				num += base_num;
			}
			return num + (base_num - tmin + 1) * delta / (delta + skew);
		}

		public string Decode(string s, int offset)
		{
			int num = initial_n;
			int num2 = 0;
			int num3 = initial_bias;
			int num4 = 0;
			StringBuilder stringBuilder = new StringBuilder();
			for (int i = 0; i < s.Length; i++)
			{
				if (s[i] == delimiter)
				{
					num4 = i;
				}
			}
			if (num4 < 0)
			{
				return s;
			}
			stringBuilder.Append(s, 0, num4);
			int num5 = ((num4 > 0) ? (num4 + 1) : 0);
			while (num5 < s.Length)
			{
				int num6 = num2;
				int num7 = 1;
				int num8 = base_num;
				while (true)
				{
					int num9 = DecodeDigit(s[num5++]);
					num2 += num9 * num7;
					int num10 = ((num8 <= num3 + tmin) ? tmin : ((num8 >= num3 + tmax) ? tmax : (num8 - num3)));
					if (num9 < num10)
					{
						break;
					}
					num7 *= base_num - num10;
					num8 += base_num;
				}
				num3 = Adapt(num2 - num6, stringBuilder.Length + 1, num6 == 0);
				num += num2 / (stringBuilder.Length + 1);
				num2 %= stringBuilder.Length + 1;
				if (num < 128)
				{
					throw new ArgumentException($"Invalid Bootstring decode result, at {offset + num5}");
				}
				stringBuilder.Insert(num2, (char)num);
				num2++;
			}
			return stringBuilder.ToString();
		}
	}
	internal class Punycode : Bootstring
	{
		public Punycode()
			: base('-', 36, 1, 26, 38, 700, 72, 128)
		{
		}
	}
	[Serializable]
	[StructLayout(LayoutKind.Sequential)]
	[ComVisible(true)]
	public class RegionInfo
	{
		private static RegionInfo currentRegion;

		private int regionId;

		private string iso2Name;

		private string iso3Name;

		private string win3Name;

		private string englishName;

		private string nativeName;

		private string currencySymbol;

		private string isoCurrencySymbol;

		private string currencyEnglishName;

		private string currencyNativeName;

		public static RegionInfo CurrentRegion
		{
			get
			{
				RegionInfo regionInfo = currentRegion;
				if (regionInfo == null)
				{
					CultureInfo currentCulture = CultureInfo.CurrentCulture;
					if (currentCulture != null)
					{
						regionInfo = new RegionInfo(currentCulture);
					}
					if (Interlocked.CompareExchange(ref currentRegion, regionInfo, null) != null)
					{
						regionInfo = currentRegion;
					}
				}
				return regionInfo;
			}
		}

		[ComVisible(false)]
		public virtual string CurrencyEnglishName => currencyEnglishName;

		public virtual string CurrencySymbol => currencySymbol;

		[MonoTODO("DisplayName currently only returns the EnglishName")]
		public virtual string DisplayName => englishName;

		public virtual string EnglishName => englishName;

		[ComVisible(false)]
		public virtual int GeoId => regionId;

		public virtual bool IsMetric
		{
			get
			{
				string text = iso2Name;
				if (text == "US" || text == "UK")
				{
					return false;
				}
				return true;
			}
		}

		public virtual string ISOCurrencySymbol => isoCurrencySymbol;

		[ComVisible(false)]
		public virtual string NativeName => nativeName;

		[ComVisible(false)]
		public virtual string CurrencyNativeName => currencyNativeName;

		public virtual string Name => iso2Name;

		public virtual string ThreeLetterISORegionName => iso3Name;

		public virtual string ThreeLetterWindowsRegionName => win3Name;

		public virtual string TwoLetterISORegionName => iso2Name;

		public RegionInfo(int culture)
		{
			if (!GetByTerritory(CultureInfo.GetCultureInfo(culture)))
			{
				throw new ArgumentException(string.Format("Region ID {0} (0x{0:X4}) is not a supported region.", culture), "culture");
			}
		}

		public RegionInfo(string name)
		{
			if (name == null)
			{
				throw new ArgumentNullException();
			}
			if (construct_internal_region_from_name(name.ToUpperInvariant()) || GetByTerritory(CultureInfo.GetCultureInfo(name)))
			{
				return;
			}
			throw new ArgumentException($"Region name {name} is not supported.", "name");
		}

		private RegionInfo(CultureInfo ci)
		{
			if (ci.LCID == 127)
			{
				regionId = 244;
				iso2Name = "IV";
				iso3Name = "ivc";
				win3Name = "IVC";
				nativeName = (englishName = "Invariant Country");
				currencySymbol = "¤";
				isoCurrencySymbol = "XDR";
				currencyEnglishName = (currencyNativeName = "International Monetary Fund");
			}
			else
			{
				if (ci.Territory == null)
				{
					throw new NotImplementedException("Neutral region info");
				}
				construct_internal_region_from_name(ci.Territory.ToUpperInvariant());
			}
		}

		private bool GetByTerritory(CultureInfo ci)
		{
			if (ci == null)
			{
				throw new Exception("INTERNAL ERROR: should not happen.");
			}
			if (ci.IsNeutralCulture || ci.Territory == null)
			{
				return false;
			}
			return construct_internal_region_from_name(ci.Territory.ToUpperInvariant());
		}

		[MethodImpl(MethodImplOptions.InternalCall)]
		private extern bool construct_internal_region_from_name(string name);

		public override bool Equals(object value)
		{
			if (value is RegionInfo regionInfo)
			{
				return Name == regionInfo.Name;
			}
			return false;
		}

		public override int GetHashCode()
		{
			return Name.GetHashCode();
		}

		public override string ToString()
		{
			return Name;
		}

		internal static void ClearCachedData()
		{
			currentRegion = null;
		}
	}
