			return true;
		}

		private bool TryDequeueSlow(out T item)
		{
			while (true)
			{
				Segment head = _head;
				if (head.TryDequeue(out item))
				{
					return true;
				}
				if (head._nextSegment == null)
				{
					item = default(T);
					return false;
				}
				if (head.TryDequeue(out item))
				{
					break;
				}
				lock (_crossSegmentLock)
				{
					if (head == _head)
					{
						_head = head._nextSegment;
					}
				}
			}
			return true;
		}

		public bool TryPeek(out T result)
		{
