										fillBuffer[i] = new KeyValuePair<long, TSource>(_sharedIndex.Value, _sharedReader.Current);
										continue;
									}
									_sourceDepleted.Value = true;
									_fillBufferSize = i;
									break;
								}
								_fillBufferCurrentPosition = 0;
							}
						}
						catch
						{
							_sourceDepleted.Value = true;
							_hasNoElementsLeft.Value = true;
							throw;
						}
					}
					return actualNumElementsGrabbed > 0;
				}

				public void Dispose()
