			}
			if (!Exists(path))
			{
				throw new DirectoryNotFoundException("Directory \"" + path + "\" not found.");
			}
			MonoIO.SetCurrentDirectory(path, out var error);
			if (error != MonoIOError.ERROR_SUCCESS)
			{
				throw MonoIO.GetException(path, error);
			}
		}
	}
