			}
			if (length == 0L)
			{
				return ReadAllBytesUnknownLength(fileStream);
			}
			int num = 0;
			int num2 = (int)length;
			byte[] array = new byte[num2];
			while (num2 > 0)
			{
				int num3 = fileStream.Read(array, num, num2);
				if (num3 == 0)
				{
					throw Error.GetEndOfFile();
				}
				num += num3;
				num2 -= num3;
			}
			return array;
		}

		private static byte[] ReadAllBytesUnknownLength(FileStream fs)
