			}
			wh = new ManualResetEvent(initialState: false);
		}

		private static void CBWrapper(IAsyncResult ares)
		{
			((FileStreamAsyncResult)ares).realcb.BeginInvoke(ares, null, null);
		}

		public void SetComplete(Exception e)
		{
			exc = e;
